type Job={slug:string;keyword:string;make:string;model:string;category:string;title:string;answer:string;scope:string;detail:string;values:SpecValue[];source:Source;extraSources?:Source[];diagram?:"wheel"|"spark"|"firing"|"oil"|"timing"|"main"|"intake"|"head";image?:"engine"|"vehicle"};
const jobs:Job[]=[
  {slug:"chevrolet/silverado-1500/spark-plug-gap-chart",keyword:"chevy silverado spark plug gap specs",make:"Chevrolet",model:"2004 Silverado 1500 5.3L",category:"Ignition Specs",title:"2004 Silverado 5.3 Spark Plug Gap and Torque",answer:"For the covered 2004 Silverado 1500 5.3L VIN T, GM's updated service information specifies a 0.040-in (1.01-mm) factory gap for iridium P/N 12571164 / ACDelco 41-985 plugs. The matching service row lists 11 lb-ft (15 N·m) installation torque.",scope:"This exact answer is tied to the 2004 Silverado 1500 4WD 5.3L VIN T and the replacement-plug bulletin incorporated into its service data. Other years, engines and superseded plug numbers require their own catalog and service row.",detail:"GM states the gap is set during manufacture and should not be changed; reject a new plug that is not correctly gapped. Confirm the current approved part-number supersession before purchase and install into clean, undamaged threads.",values:[{label:"Factory plug gap",value:"0.040 in",note:"1.01 mm"},{label:"Bulletin plug",value:"GM 12571164",note:"ACDelco 41-985"},{label:"Installation torque",value:"11 lb-ft",note:"15 N·m"},{label:"Gap adjustment",value:"Do not alter",note:"Factory-set iridium tip"}],source:silverado2004Spark,diagram:"spark",image:"engine"},
  {slug:"ram/1500/towing-capacity",keyword:"dodge ram 1500 towing capacity chart",make:"Ram",model:"2026 Ram 1500",category:"Vehicle Specifications",title:"2026 Ram 1500 Towing Capacity by Engine and Configuration",answer:"The 2026 Ram 1500 reaches 11,610 lb maximum conventional towing in the factory SAE J2807 chart with the standard-output 3.0L Hurricane, 3.92 axle, Quad Cab 4x2 configuration. Other engines, cabs, beds and 4x4 combinations are lower.",scope:"This page covers the U.S. 2026 Ram 1500 DT chart. It does not apply to a Classic/DS truck, Ram 2500/3500, another model year or an assumed configuration based only on the engine badge.",detail:"Ram's chart lists engine, transmission, axle ratio, GCWR, cab, bed and drivetrain together because every field changes the rating. Use the truck's VIN/build data and door-label payload, then count occupants, cargo, accessories and tongue weight before selecting a trailer.",values:[{label:"3.0L Hurricane SO maximum",value:"11,610 lb",note:"3.92, Quad Cab 4x2"},{label:"5.7L HEMI maximum",value:"11,320 lb",note:"3.92, qualifying Crew Cab 4x2"},{label:"3.6L Pentastar maximum",value:"8,130 lb",note:"Qualifying Quad Cab 4x2"},{label:"Hurricane H/O maximum",value:"10,000 lb",note:"Qualifying Limited 4x4"}],source:ram15002026Tow,diagram:"main"},
  {slug:"honda/civic/tire-pressure",keyword:"honda civic tire pressure specifications",make:"Honda",model:"2025 Civic Hatchback",category:"Vehicle Specifications",title:"2025 Honda Civic Hatchback Tire Pressure by Wheel Package",answer:"For the 2025 Civic Hatchback with factory 235/40R18 tires, Honda specifies 33 psi front and 32 psi rear. The Civic Type R's 265/30ZR19 tires use 35 psi front and 33 psi rear.",scope:"These are cold pressures for the two tire rows in the U.S. 2025 Civic Hatchback manual. Sedan, Si, earlier model years and non-factory tire sizes can have different placards and should not inherit these numbers.",detail:"Measure after the car has been parked for at least three hours or driven less than one mile. A hot reading can be 4–6 psi higher; do not bleed a warm tire down to the cold target. After changing pressure on U.S. models, carry out the manual's TPMS calibration procedure. The driver-door label remains the vehicle-specific final check.",values:[{label:"235/40R18 front",value:"33 psi cold",note:"230 kPa"},{label:"235/40R18 rear",value:"32 psi cold",note:"220 kPa"},{label:"Type R 265/30ZR19 front",value:"35 psi cold",note:"240 kPa"},{label:"Type R 265/30ZR19 rear",value:"33 psi cold",note:"230 kPa"}],source:hondaCivicHatch2025,diagram:"wheel"},
  {slug:"bmw/3-series/brake-rotor-size",keyword:"bmw 3 series brake rotor size chart",make:"BMW",model:"2011 E90 3 Series",category:"Brake Specifications",title:"2011 BMW E90 Brake Rotor Size and Wear-Limit Chart",answer:"BMW's 2011 E90 technical data lists several front and rear rotor sizes because engine, transmission and equipment change the brake package. The correct disc must be assigned by VIN and the BMW Electronic Parts Catalogue, not by '328i' or wheel diameter alone.",scope:"This chart is scoped to the cited 2011 E90 service data. It summarizes published E90 combinations and inspection rules; it does not assert that every listed rotor fits the covered N52K sedan.",detail:"BMW requires new discs in axle pairs and new pads with replacement discs. Minimum thickness is stamped on the disc body; general inspection uses nominal thickness minus 2.4 mm for ordinary discs, while perforated/M applications follow a different 1.6-mm rule.",values:[{label:"Published front combinations",value:"292–360 mm diameter",note:"22–30 mm nominal thickness; option dependent"},{label:"Published rear combinations",value:"296–350 mm diameter",note:"10–24 mm nominal thickness; option dependent"},{label:"Ordinary-disc GI reference",value:"Nominal minus 2.4 mm",note:"Stamped MIN TH still controls"},{label:"Fitment authority",value:"VIN + BMW ETK",note:"Engine/equipment dependent"}],source:bmwE90FrontRotors,extraSources:[bmwE90RearRotors],diagram:"wheel"},
  {slug:"nissan/altima/transmission-fluid-capacity",keyword:"nissan altima transmission fluid capacity",make:"Nissan",model:"2024 Altima",category:"Fluid Capacities",title:"2024 Nissan Altima CVT Fluid: Why the Manual Lists No Fixed Capacity",answer:"Nissan does not publish a universal quart capacity for the 2024 Altima CVT in the owner-manual capacity table. It specifies Genuine Nissan CVT Fluid NS-3 or an equivalent meeting that requirement and directs the system to be filled by the proper service-level procedure.",scope:"This answer applies to the U.S.-market 2024 Altima Xtronic CVT. It does not cover an older conventional automatic, a manual transmission, another Nissan CVT generation or an assumed dry-build capacity from a parts database.",detail:"The omission is meaningful: a pan drain removes only part of the system volume, while a dry transmission, cooler-line repair and component replacement retain different amounts. Measure what was removed only as a planning reference, then use the factory temperature-dependent level procedure and correct equipment. Do not substitute NS-2, ordinary ATF or a generic multi-vehicle fluid, and do not mix products that lack the NS-3 equivalency statement.",values:[{label:"Published owner-manual capacity",value:"Not specified",note:"Dashes in the capacity table"},{label:"Required CVT fluid",value:"Nissan NS-3 or equivalent",note:"Do not mix with other fluids"},{label:"Drain-and-fill quantity",value:"Amount removed varies",note:"Not total system capacity"},{label:"Final level",value:"Temperature-based service procedure",note:"Bottle count is not a level check"}],source:nissanAltima2024Cvt,diagram:"oil"},
  {slug:"jeep/wrangler/bolt-pattern",keyword:"jeep wrangler bolt pattern specifications",make:"Jeep",model:"2012 Wrangler JK",category:"Vehicle Specifications",title:"2012 Jeep Wrangler JK Bolt Pattern and Wheel Hardware",answer:"The 2012 Jeep Wrangler JK uses a five-lug, 5 x 127-mm (5 x 5-in) bolt circle. Its factory service row identifies 1/2-20 wheel studs and 60-degree cone-seat nuts, with a published wheel-nut torque range of 125–180 N·m (92–132 lb-ft).",scope:"This page is deliberately scoped to the 2012 U.S.-market Wrangler JK 3.6L. It does not apply the JK pattern, stud thread or torque range to a YJ, TJ, JL, aftermarket axle or wheel conversion.",detail:"Bolt circle alone cannot establish wheel fit. Confirm center-bore engagement, backspacing/offset, brake and steering clearance, load rating and the wheel maker's approved 60-degree seat before mounting. Do not lubricate the stud or cone unless the exact wheel procedure says to revise the dry-thread torque.",values:[{label:"Bolt pattern",value:"5 x 127 mm",note:"5 x 5 in; five lugs"},{label:"Wheel-stud thread",value:"1/2-20",note:"2012 JK factory row"},{label:"Lug-nut seat",value:"60° cone",note:"Match the wheel seat"},{label:"Wheel-nut torque range",value:"92–132 lb-ft",note:"125–180 N·m"}],source:jeepWrangler2012Wheel,diagram:"wheel"},
  {slug:"subaru/outback/alternator-amperage",keyword:"subaru outback alternator amperage specs",make:"Subaru",model:"2005 Outback 2.5L",category:"Electrical Specifications",title:"2005 Subaru Outback 2.5 Alternator Amperage Specs",answer:"The 2005 naturally aspirated Outback 2.5L service table specifies a Mitsubishi Electric A003TG2391ZC alternator rated at 12 volts and 110 amps.",scope:"These values apply to the cited 2005 Outback 2.5L SOHC non-turbo application. Turbo, 3.0L, later smart-charging systems and different option packages require their own alternator part and test row.",detail:"The factory table also gives minimum controlled-test output of 50 A at 1,500 rpm, 91 A at 2,500 rpm and 105 A at 5,000 rpm, plus 14.1–14.8 V regulated voltage at 20°C. Those bench-style points are not a command to rev an installed engine to 5,000 rpm for a driveway test.",values:[{label:"Rated output",value:"110 A",note:"12-V generator"},{label:"Generator model",value:"A003TG2391ZC",note:"Mitsubishi Electric"},{label:"Minimum test output",value:"50 / 91 / 105 A",note:"At 1,500 / 2,500 / 5,000 rpm"},{label:"Regulated voltage",value:"14.1–14.8 V",note:"At 20°C / 68°F"}],source:subaruOutback2005Alternator,diagram:"timing"},
  {slug:"hyundai/elantra/spark-plug-torque",keyword:"hyundai elantra spark plug torque specs",make:"Hyundai",model:"2012 Elantra 1.8L",category:"Ignition Specs",title:"2012 Hyundai Elantra Spark Plug Torque and Gap",answer:"For the 2012 Elantra 1.8L, Hyundai's service procedure lists 14.7–24.5 N·m (10.8–18.1 lb-ft) for the spark plugs, 9.8–11.8 N·m for the ignition coils and a 1.0–1.1-mm plug gap.",scope:"These figures apply to the cited 2012 Elantra 1.8L application. Turbo, 2.0L, Elantra Touring and later Smartstream engines require separate plug and coil specifications.",detail:"The factory table identifies SILZKR6B11 and RER8WMPB4 plug types for the covered application. Keep contaminants out of the wells, hand-start plugs in a cool head and do not convert the published range into a universal Hyundai value.",values:[{label:"Spark plug torque",value:"14.7–24.5 N·m",note:"10.8–18.1 lb-ft"},{label:"Ignition coil torque",value:"9.8–11.8 N·m",note:"7.2–8.7 lb-ft"},{label:"Electrode gap",value:"1.0–1.1 mm",note:"0.0394–0.0433 in"},{label:"Listed plug types",value:"SILZKR6B11 / RER8WMPB4",note:"Verify current catalog supersession"}],source:hyundaiElantra2012Spark,diagram:"spark",image:"engine"},
  {slug:"ford/mustang/horsepower-by-year",keyword:"ford mustang horsepower specs by year",make:"Ford",model:"Mustang GT and performance models",category:"Engine Specifications",title:"Ford Mustang Horsepower by Year: Selected Factory Milestones",answer:"Ford's published milestones show how sharply the Mustang's output changes by engine and trim: the 2011 GT introduced a 412-hp 5.0L Coyote, the 2018 GT reached 460 hp, and the 2024 range spans 315 hp for EcoBoost, 480 or 486 hp for GT and 500 hp for Dark Horse.",scope:"This is a selected U.S.-market factory milestone chart, not one horsepower figure for every Mustang sold in each year. Shelby, Mach 1, Boss, Cobra, Bullitt, regional versions and midyear calibrations require their own rows.",detail:"Pre-1972 advertised gross horsepower is not directly comparable with later SAE net ratings measured with production accessories and exhaust. Fuel requirements also matter: Ford's 2024 figures are based on premium fuel under SAE J1349, and the active-valve GT exhaust changes the rated result.",values:[{label:"2011 Mustang GT",value:"412 hp",note:"5.0L Coyote launch rating"},{label:"2018 Mustang GT",value:"460 hp",note:"5.0L V8"},{label:"2024 EcoBoost",value:"315 hp",note:"2.3L; premium fuel basis"},{label:"2024 Mustang GT",value:"480 / 486 hp",note:"Standard / active-valve exhaust"},{label:"2024 Dark Horse",value:"500 hp",note:"5.0L; premium fuel basis"}],source:fordMustangMilestones,extraSources:[fordMustang2018,fordMustang2024],diagram:"main",image:"engine"},
  {slug:"chevrolet/tahoe/rear-axle-torque",keyword:"chevy tahoe rear axle torque specs",make:"Chevrolet",model:"2012 Tahoe 5.3L 4WD",category:"Torque Specs",title:"2012 Chevy Tahoe Rear Axle Torque Specifications",answer:"The 2012 Tahoe 5.3L rear-drive-axle table separates 8.6-, 9.5-LD and 10.5-inch hardware. All three list 39 N·m (29 lb-ft) for rear cover bolts and 33 N·m (24 lb-ft) for the fill plug, while bearing-cap and ring-gear values differ by axle.",scope:"These values are tied to the cited 2012 Tahoe 4WD 5.3L service table. Identify the installed axle by RPO and physical/service information before selecting a row; do not infer it from trim or differential-cover shape alone.",detail:"This is not a pinion-nut shortcut. Pinion bearing preload requires a separate measured procedure. The table's bearing-cap and ring-gear values apply only during correctly identified differential service with the required fastener condition.",values:[{label:"Rear cover bolts",value:"39 N·m",note:"29 lb-ft; all three listed axles"},{label:"Fill plug",value:"33 N·m",note:"24 lb-ft"},{label:"Bearing-cap bolts",value:"75 / 95 / 185 N·m",note:"8.6 / 9.5 LD / 10.5-inch"},{label:"Ring-gear bolts",value:"120 / 140 / 165 N·m",note:"8.6 / 9.5 LD / 10.5-inch"}],source:chevroletTahoe2012RearAxle,diagram:"main"},
  {slug:"toyota/camry/serpentine-belt-diagram",keyword:"toyota camry serpentine belt diagram",make:"Toyota",model:"2010 Camry 2.5L",category:"Diagrams",title:"2010 Toyota Camry 2.5 Belt Routing: Two-Belt Layout",answer:"The 2010 Camry 2.5L 2AR-FE does not use one conventional serpentine belt. Toyota shows two V-ribbed drives: a compressor/generator belt routed around the crankshaft, A/C compressor, water pump, generator and its tensioner, plus a separate vane-pump belt around the crankshaft, vane pump, idler and tensioner.",scope:"This routing applies to the cited non-hybrid 2010 Camry 2.5L 2AR-FE. The 2.4L, 3.5L V6, hybrid and later Camry accessory layouts are different and must not inherit this diagram.",detail:"Toyota specifies a high-strength aramid-core belt for the compressor/generator drive. Rotate each automatic tensioner clockwise to unload it. During installation, place the first belt on every pulley except the water pump before slipping it over that pulley; place the vane-pump belt on every pulley except its tensioner before completing the route.",values:[{label:"Drive layout",value:"Two V-ribbed belts",note:"Not one serpentine belt"},{label:"Main-belt accessories",value:"A/C, water pump, generator",note:"Crankshaft + tensioner"},{label:"Second-belt accessory",value:"Vane pump",note:"Crankshaft + idler + tensioner"},{label:"Tensioner release",value:"Rotate clockwise",note:"Both belt procedures"}],source:toyotaCamry2010Belts,diagram:"timing",image:"engine"},
  {slug:"dodge/charger/firing-order",keyword:"dodge charger firing order specifications",make:"Dodge",model:"2012 Charger",category:"Firing Order",title:"2012 Dodge Charger Firing Order: 3.6L vs. 5.7L",answer:"Factory service data lists 1-2-3-4-5-6 for the 2012 Charger 3.6L V6 and 1-8-4-3-6-5-7-2 for the 2012 Charger 5.7L HEMI V8.",scope:"These rows cover the cited 2012 AWD 3.6L and AWD 5.7L applications. They do not identify a classic Charger engine, the 6.4L SRT application or a different model-year ignition system.",detail:"Firing sequence is not a cylinder-location diagram. Read the misfire cylinder from the correct engine layout, label connectors before moving coils, and do not swap a V6 sequence into a HEMI diagnostic plan.",values:[{label:"3.6L V6 firing order",value:"1-2-3-4-5-6",note:"2012 AWD factory row"},{label:"5.7L HEMI firing order",value:"1-8-4-3-6-5-7-2",note:"2012 AWD factory row"},{label:"Code interpretation",value:"P030x = physical cylinder x",note:"Not event position"}],source:dodgeCharger36Firing,extraSources:[dodgeCharger57Firing],diagram:"firing",image:"engine"},
  {slug:"bmw/5-series/battery-replacement",keyword:"bmw 5 series battery replacement specs",make:"BMW",model:"2011 528i F10",category:"Electrical Specifications",title:"2011 BMW 528i F10 Battery Replacement and Registration",answer:"On the 2011 BMW 528i F10, the replacement battery must follow the VIN-assigned capacity, chemistry and installation location. BMW requires the new battery to be registered on vehicles equipped with the Intelligent Battery Sensor or power module.",scope:"This procedure is tied to the cited 2011 F10 528i. It does not claim that every 5 Series uses one amp-hour rating, case size or AGM battery; the BMW parts assignment and the label on the installed battery control selection.",detail:"Registration tells the energy-management system that a new battery has been installed. If capacity or chemistry changes, BMW says the vehicle data must also be programmed through the battery-retrofit path. Registration alone does not correctly encode an unapproved size change.",values:[{label:"Replacement selection",value:"VIN-assigned battery",note:"Match capacity, type and location"},{label:"After like-for-like installation",value:"Register battery",note:"IBS/power-module vehicles"},{label:"Capacity or chemistry change",value:"Program vehicle data",note:"Battery-retrofit procedure"},{label:"AGM substitution",value:"Same specifications only",note:"Otherwise coding is required"}],source:bmwF102011Battery,diagram:"main"},
  {slug:"nissan/maxima/oil-capacity",keyword:"nissan maxima oil capacity chart",make:"Nissan",model:"2023 Maxima 3.5L",category:"Fluid Capacities",title:"2023 Nissan Maxima Oil Capacity: Filter vs. No-Filter Refill",answer:"For the final-year 2023 Maxima 3.5L V6, Nissan specifies approximately 5.125 US qt (4.8 L) with a new oil filter and 4.75 US qt (4.5 L) when the filter is retained.",scope:"These figures apply specifically to the U.S.-market 2023 Maxima and its VQ35DE 3.5L V6. Earlier Maxima generations and other Nissan VQ applications can use different pans, filters or published quantities.",detail:"Use synthetic SAE 0W-20 meeting API SP and ILSAC GF-6, or the equivalent oil described by Nissan. Capacity remains approximate because drain time and oil temperature change the amount recovered. Refill short, run the engine and inspect the drain plug and filter, shut down on level ground, allow adequate drain-back and bring the dipstick to the proper mark without overfilling.",values:[{label:"Oil and filter change",value:"5.125 US qt",note:"4.8 L; 4-1/4 Imperial qt"},{label:"Oil change, filter retained",value:"4.75 US qt",note:"4.5 L; 4 Imperial qt"},{label:"Recommended viscosity",value:"SAE 0W-20",note:"Synthetic"},{label:"Required quality",value:"API SP / ILSAC GF-6",note:"Use dipstick for final level"}],source:nissanMaxima2023,diagram:"oil"},
  {slug:"jeep/grand-cherokee/towing-capacity",keyword:"jeep grand cherokee towing specs",make:"Jeep",model:"2022 Grand Cherokee 4xe",category:"Vehicle Specifications",title:"2022 Jeep Grand Cherokee 4xe Towing Capacity and Limits",answer:"The 2022 two-row Jeep Grand Cherokee 4xe AWD is rated for a maximum gross trailer weight of 6,000 lb (2,722 kg), with maximum trailer tongue weight of 600 lb (272 kg).",scope:"This exact row is for the 2022 WL two-row Grand Cherokee 4xe with the 2.0L plug-in-hybrid powertrain and AWD. It does not describe a Grand Cherokee L, a 3.6L or 5.7L model, or earlier WK2 vehicles.",detail:"The same factory chart lists a 12,125-lb GCWR and a 40-sq-ft trailer frontal-area limit. The 6,000-lb number is a ceiling, not a payload allowance: tongue weight, occupants, charging gear, accessories and cargo must still fit the vehicle's door-label payload and axle ratings. Use the lower of the vehicle, hitch and trailer limits.",values:[{label:"Maximum gross trailer weight",value:"6,000 lb",note:"2,722 kg"},{label:"Maximum tongue weight",value:"600 lb",note:"272 kg"},{label:"GCWR",value:"12,125 lb",note:"5,568 kg in Mopar chart"},{label:"Maximum frontal area",value:"40 sq ft",note:"3.72 m²"}],source:jeepGrandCherokee4xe2022,diagram:"main"},
  {slug:"subaru/forester/tire-size",keyword:"subaru forester tire size specifications",make:"Subaru",model:"2012 Forester 2.5L",category:"Vehicle Specifications",title:"2012 Subaru Forester Tire Size and Wheel Specifications",answer:"Subaru's 2012 Forester 2.5L table lists P215/65R16 96H tires on 16 x 6.5 J/JJ wheels and P225/55R17 95H tires on 17 x 7 J/JJ wheels. Both factory wheel rows use 48-mm offset and a 100-mm pitch-circle diameter.",scope:"This page is scoped to the cited naturally aspirated 2012 Forester 2.5L service table. Turbo models, another market, a different model year or an aftermarket wheel package require separate load, clearance and placard checks.",detail:"The size molded into the tire does not supply the vehicle's normal inflation pressure. Subaru points to the tire-information label on the driver's door pillar. Match size, load index, speed symbol, rim width and all four rolling circumferences for AWD service.",values:[{label:"16-inch package",value:"P215/65R16 96H",note:"16 x 6.5 J/JJ wheel"},{label:"17-inch package",value:"P225/55R17 95H",note:"17 x 7 J/JJ wheel"},{label:"Factory offset",value:"48 mm",note:"1.89 in; both listed rows"},{label:"Pitch-circle diameter",value:"100 mm",note:"3.94 in; both listed rows"}],source:subaruForester2012Tires,diagram:"wheel"},
  {slug:"hyundai/sonata/head-bolt-torque",keyword:"hyundai sonata head bolt torque specs",make:"Hyundai",model:"2012 Sonata 2.4L",category:"Torque Specs",title:"2012 Hyundai Sonata 2.4 Head Bolt Torque Stages",answer:"Hyundai's 2012 Sonata 2.4L procedure calls for new, dry cylinder-head bolts: tighten in sequence to 32.4–36.3 N·m (23.9–26.8 lb-ft), then turn each bolt 90–95 degrees and repeat with a second 90–95-degree pass.",scope:"This three-stage procedure is tied to the cited 2012 naturally aspirated 2.4L application and its illustrated order. It must not be transferred to the 2.0T, hybrid, later Smartstream engine or another gasket/bolt design.",detail:"Hyundai explicitly says not to apply engine oil to these bolts and to always use new bolts. The sequence diagram and angle accuracy are part of the specification; a final torque number cannot replace either angle pass.",values:[{label:"Stage 1",value:"32.4–36.3 N·m",note:"23.9–26.8 lb-ft; sequence order"},{label:"Stage 2",value:"90–95°",note:"Continue in sequence"},{label:"Stage 3",value:"90–95°",note:"Second angle pass"},{label:"Bolt condition",value:"New and dry",note:"Do not apply engine oil"}],source:hyundaiSonata2012Head,diagram:"head",image:"engine"},
  {slug:"ford/explorer/fuel-tank-capacity",keyword:"ford explorer fuel tank capacity specs",make:"Ford",model:"2026 Explorer",category:"Fluid Capacities",title:"2026 Ford Explorer Fuel Tank Capacity by Engine",answer:"Ford lists a 17.9-US-gal (67.8-L) tank for the 2026 Explorer 2.3L, a 20.2-US-gal (76.5-L) tank for non-hybrid 3.0L and 3.3L models, and an 18.0-US-gal (68.1-L) tank for the full hybrid.",scope:"These figures are for the U.S.-market 2026 Explorer. They must not be transferred to an earlier generation or another market simply because the engine badge appears similar.",detail:"Ford describes advertised capacity as the maximum fuel that can be added when the gauge indicates empty. A reserve remains in the tank, so a normal pump receipt can be lower than the published capacity without indicating a fault.",values:[{label:"2.3L non-hybrid",value:"17.9 US gal",note:"67.8 L"},{label:"3.0L / 3.3L non-hybrid",value:"20.2 US gal",note:"76.5 L"},{label:"Full hybrid",value:"18.0 US gal",note:"68.1 L"},{label:"Gauge at empty",value:"Reserve remains",note:"Refill can be less than tank capacity"}],source:fordExplorer2026,diagram:"oil"},
  {slug:"chevrolet/equinox/oil-filter-size",keyword:"chevy equinox oil filter size specs",make:"Chevrolet",model:"2012 Equinox 2.4L",category:"Fluid Capacities",title:"2012 Chevy Equinox 2.4 Oil Filter Type and Service",answer:"The 2012 Equinox 2.4L uses a replaceable cartridge insert inside a reusable cap, not a conventional spin-on canister. GM calls for the application-specific high-performance insert, a new cap seal and 22 N·m (16 lb-ft) cap torque.",scope:"This procedure is for the cited 2012 Equinox AWD 2.4L LAF/LEA-family installation. The 3.0L V6 and later turbo generations use different filter hardware and must be looked up by VIN/engine.",detail:"GM identifies EN-44887 as the oil-filter-cap wrench and warns that another filter can fail or cause severe engine damage. Buy by approved OE cross-reference rather than an outside diameter alone; cartridge dimensions do not establish bypass behavior or media specification.",values:[{label:"Filter construction",value:"Cartridge insert",note:"Reusable cap; not spin-on"},{label:"Cap tool",value:"EN-44887",note:"Factory service tool reference"},{label:"Oil-filter cap torque",value:"22 N·m",note:"16 lb-ft"},{label:"Drain-plug torque",value:"25 N·m",note:"18 lb-ft; new seal"}],source:chevroletEquinox2012Filter,diagram:"oil"},
  {slug:"toyota/rav4/brake-pad-thickness",keyword:"toyota rav4 brake pad thickness chart",make:"Toyota",model:"2010 RAV4 2.5L 4WD",category:"Brake Specifications",title:"2010 Toyota RAV4 Brake Pad Thickness and Limits",answer:"For the 2010 RAV4 4WD 2.5L, Toyota lists 12.0 mm as standard front lining thickness and 10.5 mm as standard rear thickness. The minimum is 1.0 mm (0.0394 in) at both axles.",scope:"These exact measurements apply to the cited 2010 RAV4 4WD 2AR-FE service row. V6, 2WD, hybrid, Prime and other generations must be checked against their own brake package.",detail:"Measure friction material only, not the steel backing plate, and inspect every inner and outer pad at its thinnest usable point. Taper, cracking, separation, glazing or fluid contamination can require replacement before the numerical minimum.",values:[{label:"Front standard thickness",value:"12.0 mm",note:"0.472 in"},{label:"Front minimum",value:"1.0 mm",note:"0.0394 in"},{label:"Rear standard thickness",value:"10.5 mm",note:"0.413 in"},{label:"Rear minimum",value:"1.0 mm",note:"0.0394 in"}],source:toyotaRav42010Pads,diagram:"wheel"},
  {slug:"dodge/durango/transmission-fluid",keyword:"dodge durango transmission fluid specs",make:"Dodge",model:"2012 Durango 5.7L 4WD",category:"Fluid Capacities",title:"2012 Dodge Durango Transmission Fluid Type and Capacity",answer:"For the 2012 Durango 5.7L 4WD with the 65RFE, factory data specifies Mopar ATF+4, a 6.5-US-qt (6.2-L) service fill and a 16.9-US-qt (16-L) overhaul fill. Service and dry-fill numbers are not interchangeable.",scope:"These exact 65RFE values cover the cited 2012 4WD 5.7L application. The same factory table lists separate NAG1 figures, and later eight-speed Durangos require different fluid and procedures.",detail:"A service fill is an approximate pan/filter operation; overhaul fill is a dry-system reference affected by cooler and line volume. Establish final level with the exact temperature and level-check procedure rather than pouring in the table quantity blindly.",values:[{label:"Required fluid",value:"Mopar ATF+4",note:"65RFE and cited NAG1 table"},{label:"65RFE 4WD service fill",value:"6.5 US qt",note:"6.2 L"},{label:"65RFE 4WD overhaul fill",value:"16.9 US qt",note:"16 L; dry reference"},{label:"NAG1 service / overhaul",value:"5.3 / 8.1 US qt",note:"5.0 / 7.7 L; separate transmission"}],source:dodgeDurango2012Atf,diagram:"oil"},
  {slug:"honda/cr-v/spark-plug-gap",keyword:"honda CR-V spark plug gap specs",make:"Honda",model:"2005 CR-V 2.4L",category:"Ignition Specs",title:"2005 Honda CR-V Spark Plug Gap and Torque",answer:"For the 2005 CR-V 2.4L, Honda service data lists a new-plug gap of 1.0–1.1 mm (0.039–0.043 in) and an installation torque of 18 N·m (13 lb-ft). It instructs technicians not to adjust iridium-tip plug gaps.",scope:"These values are for the 2005 CR-V 2.4L application. They must not be transferred to later 1.5L turbo engines or another K-series vehicle without checking its exact approved plug and service procedure.",detail:"If a new iridium plug measures outside specification, replace it instead of bending the electrodes. Match the complete approved part number, inspect the gasket and porcelain, and hand-start each plug into a cool head.",values:[{label:"New-plug gap",value:"1.0–1.1 mm",note:"0.039–0.043 in"},{label:"Installation torque",value:"18 N·m",note:"13 lb-ft"},{label:"Iridium gap adjustment",value:"Do not adjust",note:"Replace if out of specification"},{label:"Application",value:"2005 CR-V 2.4L",note:"K24 service row"}],source:hondaCrv2005Spark,diagram:"spark",image:"engine"},
  {slug:"nissan/rogue/tire-pressure",keyword:"nissan rogue tire pressure specifications",make:"Nissan",model:"2024 Rogue",category:"Vehicle Specifications",title:"2024 Nissan Rogue Tire Pressure by Tire Size",answer:"For the 2024 Rogue, Nissan specifies 36 psi front and 33 psi rear with 235/65R17 tires. Factory 235/60R18 and 235/55R19 packages use 33 psi front and 30 psi rear, all measured cold.",scope:"These values apply to the U.S.-market 2024 Rogue and the tire sizes shown in its manual. Rogue Sport, temporary spares, replacement wheel packages and other model years use their own labels.",detail:"Confirm the driver-door tire-and-loading placard before adjustment. The sidewall number is the tire's maximum permissible pressure, not Nissan's normal cold target, and a warm tire should not be bled down to the cold figure.",values:[{label:"235/65R17 front",value:"36 psi cold",note:"250 kPa"},{label:"235/65R17 rear",value:"33 psi cold",note:"230 kPa"},{label:"235/60R18 or 235/55R19 front",value:"33 psi cold",note:"230 kPa"},{label:"235/60R18 or 235/55R19 rear",value:"30 psi cold",note:"210 kPa"}],source:nissanRogue2024,diagram:"wheel"},
  {slug:"jeep/cherokee/alternator-replacement",keyword:"jeep cherokee alternator replacement specs",make:"Jeep",model:"2000 Cherokee 4.0L",category:"Electrical Specifications",title:"2000 Jeep Cherokee 4.0 Alternator Ratings and Replacement",answer:"Jeep's 2000 Cherokee 4.0L table lists three Denso alternators: P/N 56041565AA at 81 A, 56041685AA at 117 A and 56041822AA at 124 A. Replacement must match the installed part and electrical package, not simply the largest output.",scope:"These ratings apply to the cited 2000 Cherokee 4WD 4.0L VIN S service data. They do not cover the later KL Cherokee or every XJ year, connector, pulley or PCM calibration.",detail:"Minimum test outputs are 57 A, 88 A and 90 A respectively under the factory test conditions. The mounting and pivot fasteners are listed at 55 N·m; disconnect the battery and follow the full belt/charging procedure before removal.",values:[{label:"Denso 56041565AA",value:"81 A rated",note:"57 A minimum test output"},{label:"Denso 56041685AA",value:"117 A rated",note:"88 A minimum test output"},{label:"Denso 56041822AA",value:"124 A rated",note:"90 A minimum test output"},{label:"Mounting / pivot fasteners",value:"55 N·m",note:"Factory mechanical row"}],source:jeepCherokee2000Alternator,diagram:"timing"},
  {slug:"subaru/impreza/oil-capacity",keyword:"subaru impreza oil capacity specs",make:"Subaru",model:"2018 Impreza 2.0L",category:"Fluid Capacities",title:"2018 Subaru Impreza Oil Capacity and Required 0W-20",answer:"Subaru specifies 4.7 US qt (4.4 L) during an oil-and-filter change on the 2018 Impreza 2.0L.",scope:"This specification applies to the naturally aspirated U.S.-market 2018 Impreza. It is not a WRX or WRX STI value, and it should not be assumed for a different FB/EJ engine generation merely because the badge still says Impreza.",detail:"Use synthetic SAE 0W-20 meeting ILSAC GF-5 or API SN with Resource Conserving wording as stated in the guide. Refill short of 4.7 qt, circulate the oil and check for filter or drain-plug leaks, then allow drain-back on level ground and finish at the dipstick full mark. Subaru's guide shows roughly one quart between the low and full marks, but that is a correction reference—not permission to add a full quart without checking.",values:[{label:"Oil and filter change",value:"4.7 US qt",note:"4.4 L; 3.9 Imperial qt"},{label:"Engine",value:"2.0L naturally aspirated",note:"2018 Impreza"},{label:"Specified viscosity",value:"SAE 0W-20 synthetic",note:"Do not substitute WRX 5W-30 row"},{label:"Oil quality",value:"API SN RC or ILSAC GF-5",note:"Final level by dipstick"}],source:subaruImpreza2018,diagram:"oil"},
  {slug:"hyundai/tucson/towing-capacity",keyword:"hyundai tucson towing capacity chart",make:"Hyundai",model:"2026 Tucson",category:"Vehicle Specifications",title:"2026 Hyundai Tucson Towing Capacity: Braked vs. Unbraked",answer:"Hyundai's U.S. specifications rate the 2026 Tucson at up to 2,750 lb with trailer brakes and 1,650 lb without trailer brakes across the published SE, SEL, SEL Plus, XRT, SEL Premium and Limited trims.",scope:"These are 2026 U.S.-market Tucson specifications from Hyundai's comparison page. They are not ratings for an earlier Tucson, Tucson Hybrid or Plug-in Hybrid, and international tow limits can differ even when the model name looks the same.",detail:"The tow rating is only one limit. Loaded trailer weight, tongue load, passengers, cargo and hitch hardware must remain within the vehicle's certification-label payload, axle ratings and owner-manual limits. Trailer brakes do not increase the vehicle's payload capacity.",values:[{label:"Trailer with brakes",value:"2,750 lb max",note:"Published 2026 gasoline trims"},{label:"Trailer without brakes",value:"1,650 lb max",note:"Published 2026 gasoline trims"},{label:"XRT tow hitch",value:"Standard",note:"Other trims may use an accessory"},{label:"Final loading check",value:"Payload + axle limits",note:"Tongue weight counts as vehicle load"}],source:hyundaiTucson2026Tow,diagram:"main"},
  {slug:"ford/ranger/wheel-torque",keyword:"ford ranger wheel torque specs",make:"Ford",model:"2022 Ranger",category:"Torque Specs",title:"2022 Ford Ranger Wheel Nut Torque and Recheck Procedure",answer:"Ford specifies 100 lb-ft (135 N·m) for the M12 x 1.5 wheel nuts on the 2022 U.S.-market Ranger.",scope:"This exact row applies to the 2022 Ranger and its factory wheel hardware. Global-market Rangers and the redesigned North American generation can use different specifications, so the model year and market still matter.",detail:"Clean corrosion and loose particles from the hub pilot and both mounting faces, and keep the wheel-nut threads free of dirt and rust. Start every nut by hand, snug across the wheel in stages, then finish with a calibrated torque wrench. Ford directs owners to retighten the nuts within 100 miles (160 km) after the wheels have been removed.",values:[{label:"Wheel nut torque",value:"100 lb-ft",note:"135 N·m"},{label:"Thread size",value:"M12 x 1.5",note:"2022 factory hardware"},{label:"Recheck interval",value:"Within 100 mi",note:"160 km after removal"},{label:"Mounting faces",value:"Clean and corrosion-free",note:"Required for proper seating"}],source:fordRanger2022,diagram:"wheel"},
  {slug:"chevrolet/malibu/firing-order",keyword:"chevy malibu firing order specifications",make:"Chevrolet",model:"2012 Malibu 2.4L",category:"Firing Order",title:"2012 Chevy Malibu 2.4 Firing Order and Plug Specs",answer:"The 2012 Chevrolet Malibu 2.4L factory ignition table specifies a 1-3-4-2 firing order, 1.0-mm (0.040-in) spark-plug gap and 20 N·m (15 lb-ft) plug torque.",scope:"These values are for the cited 2012 Malibu 2.4L inline-four. The 3.6L V6 and other Malibu engine families have different cylinder layouts and must not inherit this firing diagram.",detail:"On an inline-four, identify physical cylinder location from the exact engine illustration before diagnosing P030x. A P0304 code points to cylinder 4; it does not mean the fourth event in 1-3-4-2.",values:[{label:"Firing order",value:"1-3-4-2",note:"2012 2.4L factory row"},{label:"Spark plug gap",value:"1.0 mm",note:"0.040 in"},{label:"Spark plug torque",value:"20 N·m",note:"15 lb-ft"},{label:"Plug type",value:"Electronic parts catalog",note:"Confirm current approved part"}],source:chevroletMalibu2012Ignition,diagram:"firing",image:"engine"},
  {slug:"toyota/corolla/spark-plug-torque",keyword:"toyota corolla spark plug torque specs",make:"Toyota",model:"2010 Corolla 1.8L",category:"Ignition Specs",title:"2010 Toyota Corolla Spark Plug Torque: 2ZR-FE",answer:"Toyota specifies 20 N·m (15 lb-ft) for the four spark plugs in the 2010 Corolla 1.8L 2ZR-FE, installed with a 14-mm spark-plug wrench.",scope:"This exact torque applies to the cited 2010 Corolla 2ZR-FE service procedure. Other Corolla engines, plug seat designs and model years require their own service data.",detail:"Use the approved plug part number, work on a cool engine and start every plug by hand. Do not add anti-seize unless the exact instructions explicitly revise torque for lubricated threads.",values:[{label:"Spark plug torque",value:"20 N·m",note:"15 lb-ft; 204 kgf-cm"},{label:"Spark plug wrench",value:"14 mm",note:"Factory procedure"},{label:"Engine",value:"1.8L 2ZR-FE",note:"2010 Corolla"},{label:"Number of plugs",value:"4",note:"One per cylinder"}],source:toyotaCorolla2010Spark,diagram:"spark",image:"engine"},
  {slug:"dodge/challenger/horsepower-by-year",keyword:"dodge challenger horsepower specs by year",make:"Dodge",model:"2023 Challenger Demon 170",category:"Engine Specifications",title:"2023 Dodge Challenger Demon 170 Horsepower: E10 vs. E85",answer:"The 2023 Challenger SRT Demon 170 produces 1,025 hp and 945 lb-ft on an E85 ethanol blend. On E10 premium gasoline, Dodge rates it at 900 hp and 810 lb-ft.",scope:"These figures apply only to the factory Demon 170 and its ethanol-sensing calibration. They do not describe a 2018 Demon, Hellcat, Redeye, Super Stock or ordinary Challenger, even though several use related supercharged 6.2L HEMI architecture.",detail:"Dodge states that output changes automatically with detected ethanol content. Maximum output becomes available above the specified high-ethanol threshold; the cluster indicates the detected state. That makes the fuel qualifier part of the specification, not a footnote that can be removed from the headline. The 1,025-hp figure occurs at 6,500 rpm and peak E85 torque at 4,200 rpm.",values:[{label:"E85 maximum output",value:"1,025 hp",note:"At 6,500 rpm"},{label:"E85 peak torque",value:"945 lb-ft",note:"At 4,200 rpm"},{label:"E10 maximum output",value:"900 hp",note:"Premium gasoline calibration"},{label:"E10 peak torque",value:"810 lb-ft",note:"Fuel-dependent factory rating"}],source:dodgeChallengerDemon170,diagram:"main",image:"engine"},
  {slug:"bmw/328i/brake-rotor-torque",keyword:"bmw 328i brake rotor torque specs",make:"BMW",model:"2011 328i E9x",category:"Brake Specifications",title:"2011 BMW 328i E9x Brake Rotor Retaining-Screw Torque",answer:"For the covered BMW E9x brake system, the small brake-disc-to-hub retaining screw is tightened to 16 N·m (12 lb-ft). It only locates the disc during assembly; it is not the caliper-carrier, guide-pin or wheel-bolt specification.",scope:"This page is scoped to the 2011 E9x 328i-family brake-disc procedure and the cited E90 service example. Brake option, axle and caliper supplier must be identified before using any other brake fastener value.",detail:"BMW's procedure requires a new retaining screw and, where removed, new caliper-carrier screws. The carrier and guide fasteners use separate torque-table entries. Never tighten the 16-N·m rotor screw to wheel-bolt torque, and never reuse 16 N·m for an unidentified caliper bolt.",values:[{label:"Disc-to-hub retaining screw",value:"16 N·m",note:"12 lb-ft"},{label:"Covered guide screw example",value:"30 N·m",note:"Teves FN system only"},{label:"Carrier screws",value:"Separate axle/caliper value",note:"BMW procedure calls for replacement"},{label:"Wheel bolts",value:"Separate specification",note:"Not a rotor fastener"}],source:bmwE90328RotorProcedure,extraSources:[bmwE90RotorTorque],diagram:"wheel"},
  {slug:"nissan/sentra/tire-size",keyword:"nissan sentra tire size specifications",make:"Nissan",model:"2024 Sentra",category:"Vehicle Specifications",title:"2024 Nissan Sentra Tire Sizes, Wheels and Pressure",answer:"The 2024 Sentra manual lists 205/60R16, 215/50R17 and 215/45R18 factory tire sizes. All three road-tire rows use 33 psi (230 kPa) front and rear when cold.",scope:"These specifications apply to the U.S.-market 2024 Sentra S, SV and SR factory packages. Replacement wheels, non-U.S. equipment and another model year must follow their own label and fitment data.",detail:"The matching wheels are 16 x 6.5, 17 x 7 and 18 x 7.5 with published offsets of 40, 48 and 43 mm respectively. Match load and speed ratings as well as size, and note Nissan's chain restriction on the covered 17- and 18-inch tire packages.",values:[{label:"16-inch tire",value:"205/60R16",note:"16 x 6.5 wheel; 40-mm offset"},{label:"17-inch tire",value:"215/50R17",note:"17 x 7 wheel; 48-mm offset"},{label:"18-inch tire",value:"215/45R18",note:"18 x 7.5 wheel; 43-mm offset"},{label:"Cold pressure",value:"33 psi front/rear",note:"230 kPa for all three rows"}],source:nissanSentra2024,diagram:"wheel"},
  {slug:"jeep/wrangler/towing-capacity",keyword:"jeep wrangler towing capacity chart",make:"Jeep",model:"2024 Wrangler",category:"Vehicle Specifications",title:"2024 Jeep Wrangler Towing: 2-Door vs. 4-Door",answer:"The 2024 Wrangler manual rates the covered two-door 2.0L and 3.6L models for 2,000 lb, while the covered four-door 2.0L, 3.6L, 6.4L and 4xe configurations are rated for 3,500 lb.",scope:"This chart is deliberately limited to the 2024 U.S.-market Wrangler rows in the cited Mopar manual. It is not a blanket rating for earlier JK models, a different axle/package, or a later configuration.",detail:"Maximum tongue weight is 200 lb on the cited two-door rows and 350 lb on the cited four-door rows. Tongue weight, passengers, accessories and cargo all consume vehicle payload; stay below GVWR, GAWR, GCWR and the limits of the hitch and trailer as well.",values:[{label:"2.0L / 3.6L two-door",value:"2,000 lb",note:"200 lb maximum tongue weight"},{label:"2.0L / 3.6L four-door",value:"3,500 lb",note:"350 lb maximum tongue weight"},{label:"2.0L 4xe four-door",value:"3,500 lb",note:"350 lb maximum tongue weight"},{label:"6.4L four-door",value:"3,500 lb",note:"350 lb maximum tongue weight"}],source:jeepWrangler2024,diagram:"main"},
  {slug:"subaru/legacy/serpentine-belt",keyword:"subaru legacy serpentine belt specs",make:"Subaru",model:"2012 Legacy 2.5L SOHC",category:"Diagrams",title:"2012 Subaru Legacy 2.5 Accessory Belt and Tensioner",answer:"The 2012 Legacy 2.5L SOHC uses an automatic V-belt tensioner: rotate the tensioner clockwise to unload and remove the accessory belt. Subaru lists 33 N·m for the tensioner-assembly fastener and 20 N·m for the idler-pulley fastener.",scope:"This procedure covers the cited 2012 Legacy naturally aspirated 2.5L SOHC accessory drive. It is not the engine's timing belt and must not be transferred to the turbo 2.5L or 3.6L six-cylinder routing.",detail:"Subaru says not to reuse a belt contaminated with oil, grease or coolant and to clean pulley grooves before installation. After fitting, confirm every rib is seated and the tension indicator remains within its marked limit.",values:[{label:"Tensioner release direction",value:"Clockwise",note:"Unload belt with proper tool"},{label:"Tensioner fastener",value:"33 N·m",note:"24.3 lb-ft"},{label:"Idler-pulley fastener",value:"20 N·m",note:"14.8 lb-ft"},{label:"Reuse condition",value:"Clean and undamaged only",note:"Reject oil/coolant contamination"}],source:subaruLegacy2012Belt,diagram:"timing",image:"engine"},
  {slug:"hyundai/santa-fe/oil-capacity",keyword:"hyundai santa fe oil capacity specs",make:"Hyundai",model:"2024 Santa Fe 2.5T",category:"Fluid Capacities",title:"2024 Hyundai Santa Fe 2.5 Turbo Oil Capacity and Oil Grade",answer:"Hyundai specifies a 6.13-US-qt (5.8-L) drain-and-refill quantity for the 2024 U.S.-market Santa Fe's Smartstream 2.5L turbo engine.",scope:"This exact row is for the redesigned 2024 MX5a Santa Fe 2.5T. It must not be applied to the hybrid's 1.6T, earlier 2.4L/2.0T engines, the old 3.3L V6, or another market's powertrain.",detail:"The same Hyundai table calls for full-synthetic SAE 0W-30 meeting API SN PLUS/SP or ILSAC GF-6. Treat 6.13 qt as a service refill reference: add most of the quantity, circulate the oil, check for leaks, wait for drain-back on level ground and finish at the dipstick's full mark. The amount recovered during draining can vary.",values:[{label:"Drain-and-refill quantity",value:"6.13 US qt",note:"5.8 L"},{label:"Engine",value:"Smartstream 2.5 T-GDI",note:"2024 U.S. Santa Fe"},{label:"Oil viscosity",value:"SAE 0W-30",note:"Full synthetic"},{label:"Required quality",value:"API SN PLUS/SP or ILSAC GF-6",note:"Use an approved oil"}],source:hyundaiSantaFe2024,diagram:"oil"},
  {slug:"chevrolet/traverse/towing-capacity",keyword:"chevy traverse towing capacity specifications",make:"Chevrolet",model:"2024 Traverse",category:"Vehicle Specifications",title:"2024 Chevy Traverse Towing Capacity: Factory 5,000-lb Maximum",answer:"Chevrolet rates the redesigned 2024 Traverse to tow up to 5,000 lb when properly equipped. The qualifier matters: 5,000 lb is the model's maximum trailering figure, not an automatic rating for every vehicle in every loading condition.",scope:"This specification applies to the U.S.-market 2024 Traverse introduced with the 2.5L turbo engine. Earlier V6 generations have their own equipment tables, and later model years should be checked against their current owner information rather than assumed identical.",detail:"Chevrolet identifies standard trailering equipment on the 2024 Z71, but trim name alone does not replace the vehicle labels and manual. Confirm the installed hitch and wiring, trailer-brake needs, GCWR and available payload. Passengers, cargo, accessories and tongue weight reduce the capacity available at the vehicle.",values:[{label:"Maximum trailer weight",value:"5,000 lb",note:"When properly equipped"},{label:"Metric equivalent",value:"2,268 kg",note:"Chevrolet factory figure"},{label:"2024 powertrain",value:"2.5L turbo",note:"Redesigned generation"},{label:"Z71 trailering equipment",value:"Standard",note:"Still verify the actual vehicle and load"}],source:chevroletTraverse2024,diagram:"main"},
  {slug:"toyota/highlander/spark-plug-gap",keyword:"toyota highlander spark plug gap chart",make:"Toyota",model:"2008 Highlander 3.5L",category:"Ignition Specs",title:"2008 Highlander 3.5 Spark Plug Gap and Torque",answer:"For the 2008 Highlander 3.5L 2GR-FE, Toyota lists a new-plug reference gap of 1.0–1.1 mm (0.039–0.043 in), a 1.4-mm (0.055-in) maximum used-plug gap and 18 N·m (13 lb-ft) installation torque.",scope:"This exact row covers the 2008 Highlander 4WD 2GR-FE application. Hybrid service access, later turbo engines and other model years must be checked separately even when a displacement badge appears familiar.",detail:"The used-plug maximum is an inspection limit, not a target for opening a new plug. Match the Toyota-approved part number and follow its fine-wire electrode handling instructions.",values:[{label:"New-plug reference gap",value:"1.0–1.1 mm",note:"0.039–0.043 in"},{label:"Used-plug maximum",value:"1.4 mm",note:"0.055 in; inspection limit"},{label:"Installation torque",value:"18 N·m",note:"13 lb-ft"},{label:"Engine",value:"3.5L 2GR-FE",note:"2008 Highlander 4WD"}],source:toyotaHighlander2008Spark,diagram:"spark",image:"engine"},
  {slug:"ram/2500/rear-axle-torque",keyword:"dodge ram 2500 rear axle torque specs",make:"Ram",model:"2012 Ram 2500 11.5-inch axle",category:"Torque Specs",title:"2012 Ram 2500 11.5-Inch Rear Axle Torque Specs",answer:"For the 2012 Ram 2500 11.5-inch AA rear axle, factory data lists 40 N·m for cover bolts, 281 N·m for bearing-cap bolts, 237 N·m for ring-gear bolts, 129 N·m for axle-flange bolts and 32 N·m for the fill plug.",scope:"These values are for the cited 2012 Ram 2500 4WD 6.7L service data and specifically its 11.5-inch AA table. The manual also contains 10.5-inch and 302RBI rows; identify the axle before selecting any specification.",detail:"Pinion torque-to-rotate is a preload measurement, not a pinion-nut final torque: the table lists 15–25 in-lb for new pinion bearings and 10–20 in-lb for original bearings. Use the full setup procedure for backlash, preload and fastener replacement rules.",values:[{label:"Cover / fill plug",value:"40 / 32 N·m",note:"30 / 24 lb-ft"},{label:"Bearing-cap bolts",value:"281 N·m",note:"207 lb-ft"},{label:"Ring-gear bolts",value:"237 N·m",note:"175 lb-ft"},{label:"Axle-flange bolts",value:"129 N·m",note:"95 lb-ft"}],source:ram25002012RearAxle,diagram:"main"},
  {slug:"honda/odyssey/brake-pad-thickness",keyword:"honda odyssey brake pad thickness specs",make:"Honda",model:"2010 Odyssey 3.5L",category:"Brake Specifications",title:"2010 Honda Odyssey Brake Pad Thickness and Limits",answer:"Honda's 2010 Odyssey table lists new front pads at 11.0–12.0 mm and new rear pads at 9.5–10.5 mm. The service limit is 1.6 mm (0.06 in) for both front and rear friction material.",scope:"These figures apply to the cited 2010 Odyssey 3.5L brake specification. Later electronic-parking-brake systems, different calipers and other generations require their own data.",detail:"Measure each inner and outer pad at the thinnest friction-material point, excluding the backing plate. Uneven wear can identify frozen slide pins, piston trouble or mounting problems and should not be averaged away.",values:[{label:"Front new thickness",value:"11.0–12.0 mm",note:"0.43–0.47 in"},{label:"Front service limit",value:"1.6 mm",note:"0.06 in"},{label:"Rear new thickness",value:"9.5–10.5 mm",note:"0.37–0.41 in"},{label:"Rear service limit",value:"1.6 mm",note:"0.06 in"}],source:hondaOdyssey2010Pads,diagram:"wheel"},
  {slug:"bmw/m3/horsepower-by-year",keyword:"bmw m3 horsepower specs by year",make:"BMW",model:"M3 U.S. generations",category:"Engine Specifications",title:"BMW M3 Horsepower by Generation: U.S. Factory Ratings",answer:"BMW USA's generation history lists 192 hp for the E30, 240 hp for the U.S. E36, 333 hp for the E46, 414 hp for the V8 E9x and 425 hp for the launch F8x. For 2025, BMW lists 473 hp for the M3, 503 hp for Competition and 523 hp for Competition xDrive.",scope:"These are selected U.S.-market ratings. European E30/E36/E46 figures, special editions, Competition Package changes, CS models and later model-year updates can differ, so chassis code alone is not a complete horsepower identifier.",detail:"Do not mix metric PS/CV with U.S. mechanical horsepower or copy a global-market figure into a U.S. table. Match model year, market, body designation, drivetrain and trim, then preserve BMW's own rating standard and fuel qualifier when comparing generations.",values:[{label:"E30 M3 (U.S.)",value:"192 hp",note:"2.3L four-cylinder"},{label:"E36 M3 (U.S.)",value:"240 hp",note:"3.0L/3.2L inline-six era"},{label:"E46 M3 (U.S.)",value:"333 hp",note:"3.2L S54 inline-six"},{label:"E9x M3 (U.S.)",value:"414 hp",note:"4.0L V8"},{label:"F8x M3 launch",value:"425 hp",note:"3.0L twin-turbo inline-six"},{label:"2025 G80 variants",value:"473 / 503 / 523 hp",note:"Base / Competition / Competition xDrive"}],source:bmwM3History,extraSources:[bmwM32025],diagram:"main",image:"engine"},
  {slug:"nissan/pathfinder/towing-capacity",keyword:"nissan pathfinder towing capacity chart",make:"Nissan",model:"2026 Pathfinder",category:"Vehicle Specifications",title:"2026 Nissan Pathfinder Towing Capacity: 3,500 vs. 6,000 lb",answer:"Nissan lists a 3,500-lb standard maximum towing capacity for the 2026 Pathfinder and up to 6,000 lb for qualifying properly equipped configurations, including vehicles with the applicable Premium package or factory towing equipment.",scope:"These are 2026 U.S.-market headline limits. Trim, drivetrain, installed equipment, trailer brakes and vehicle loading must match Nissan's configuration requirements before the 6,000-lb figure applies.",detail:"A tow rating is not spare payload. Subtract occupants, cargo, accessories and trailer tongue load from the vehicle-specific payload allowance, then check GVWR, axle ratings, hitch limits and GCWR. Use the lowest applicable limit in the entire combination.",values:[{label:"Standard maximum",value:"3,500 lb",note:"Without qualifying 6,000-lb equipment"},{label:"Properly equipped maximum",value:"6,000 lb",note:"Configuration/package dependent"},{label:"Rating check",value:"Exact trim and equipment",note:"Do not infer from V6 badge alone"},{label:"Loading check",value:"Door label and GCWR",note:"Tongue weight consumes payload"}],source:nissanPathfinder2026,diagram:"main"},
  {slug:"jeep/gladiator/payload",keyword:"jeep gladiator payload specs",make:"Jeep",model:"2024 Gladiator",category:"Vehicle Specifications",title:"2024 Jeep Gladiator Payload: Factory 1,725-lb Maximum",answer:"Jeep publishes a maximum 4x4 payload of 1,725 lb for the 2024 Gladiator when properly configured. That is the model maximum, not the payload of every trim or individual truck.",scope:"This page covers the 2024 Gladiator model maximum. The Tires and Loading Information label on the actual truck supplies its configuration-specific occupant-and-cargo allowance after factory equipment.",detail:"Driver, passengers, bed cargo, dealer-installed equipment, aftermarket accessories and trailer tongue weight all consume payload. Do not use the 1,725-lb headline in place of the truck's door label, GVWR or axle ratings.",values:[{label:"Maximum 4x4 payload",value:"1,725 lb",note:"Properly configured 2024 Gladiator"},{label:"Maximum gas towing",value:"7,700 lb",note:"Separate rating; properly equipped"},{label:"Engine output",value:"285 hp / 260 lb-ft",note:"3.6L Pentastar"},{label:"Vehicle-specific authority",value:"Door-jamb payload label",note:"Occupants and cargo combined"}],source:jeepGladiator2024,diagram:"main"},
  {slug:"subaru/crosstrek/tire-pressure",keyword:"subaru crosstrek tire pressure specifications",make:"Subaru",model:"2022 Crosstrek Hybrid",category:"Vehicle Specifications",title:"2022 Subaru Crosstrek Hybrid Tire Pressure: Front and Rear",answer:"Subaru specifies 36 psi for the front tires and 35 psi for the rear tires on the 2022 Crosstrek Hybrid, measured cold.",scope:"These values apply to the 2022 U.S.-market Crosstrek Hybrid and its factory tire configuration. Gasoline Crosstrek trims, later Wilderness models, replacement wheel packages and other model years must follow their own door-pillar label.",detail:"Check before driving or after the vehicle has been parked long enough for the tires to cool. Do not bleed pressure from a warm tire to force it down to the cold target, and do not use the maximum molded into the tire sidewall as the vehicle setting. The driver-side pressure label remains the quickest VIN-specific confirmation.",values:[{label:"Front tire pressure",value:"36 psi cold",note:"248 kPa rounded"},{label:"Rear tire pressure",value:"35 psi cold",note:"241 kPa rounded"},{label:"Final authority",value:"Driver-side pressure label",note:"Confirms the installed factory package"},{label:"Hot-tire adjustment",value:"Do not bleed to cold target",note:"Recheck after cooling"}],source:subaruCrosstrekHybrid2022,diagram:"wheel"},
];

type ResearchEditorial={sections:ContentSection[];faqs:{q:string;a:string}[]};
const researchedEditorial:Record<string,ResearchEditorial>={
  "ram/1500/towing-capacity":{sections:[
    {heading:"Read the chart as a complete truck configuration",paragraphs:["The headline 11,610-lb number belongs to one chart cell: standard-output Hurricane, 3.92 axle, Quad Cab and 4x2. Moving to 4x4, a Crew Cab or a longer bed adds vehicle weight and changes the available trailer rating even when the engine remains the same.","Start with the VIN/build sheet and axle ratio, then locate cab, bed and drivetrain in Ram's 2026 table. Do not identify a rating from the tailgate badge or engine alone. The chart's GCWR is part of the same row and must remain satisfied with the loaded truck and loaded trailer."]},
    {heading:"Payload usually decides how usable the maximum is",paragraphs:["Tongue weight presses on the truck and consumes payload with passengers, cargo, accessories and aftermarket equipment. A heavily optioned Crew Cab can reach its door-label payload or rear-axle rating before it reaches the published trailer ceiling.","Weigh the combination as used, including water, batteries, propane and cargo in a travel trailer. Verify receiver, ball mount, ball, coupler, tires and trailer brakes, and use the lowest applicable rating. Ram explicitly says the 1500 is not intended for fifth-wheel or gooseneck towing; those high-pin-weight trailers belong in the heavy-duty range."]}
  ],faqs:[{q:"What is the maximum 2026 Ram 1500 towing capacity?",a:"The factory chart reaches 11,610 lb with the standard-output 3.0L Hurricane, 3.92 axle, Quad Cab 4x2 configuration."},{q:"How much can the 2026 Ram 1500 5.7 HEMI tow?",a:"The chart's maximum HEMI cell is 11,320 lb, but other HEMI cab, drivetrain and axle combinations are lower."},{q:"Does tongue weight count against Ram 1500 payload?",a:"Yes. Tongue weight, occupants, cargo and accessories all consume the truck's vehicle-specific payload."},{q:"Can a 2026 Ram 1500 tow a fifth-wheel trailer?",a:"Ram says no; the 1500 does not support fifth-wheel or gooseneck towing and directs those applications toward heavy-duty trucks."}]},
  "ford/mustang/horsepower-by-year":{sections:[
    {heading:"Why one horsepower number cannot represent a model year",paragraphs:["Mustang years routinely contain several engines and performance trims. In 2024 alone, Ford lists 315 hp for EcoBoost, 480 hp for the ordinary GT, 486 hp for a GT with active-valve performance exhaust and 500 hp for Dark Horse. A search result that says '2024 Mustang horsepower' without the engine is incomplete.","Treat this table as milestones, then identify the VIN, engine and trim for a specific car. Boss, Mach 1, Bullitt, Cobra and Shelby variants have their own calibration and published rating, and a mid-cycle change can alter output without changing the generation name."]},
    {heading:"Gross, net, fuel and regional standards",paragraphs:["Older Mustang advertising often used SAE gross horsepower measured under different conditions from modern SAE net ratings. That makes a 1960s figure unsuitable for a simple mathematical comparison with a 2011 or 2024 road-car rating.","Ford states the 2024 outputs on premium fuel under SAE J1349 and distinguishes the GT's exhaust options. Preserve those qualifiers. Do not substitute metric PS from another market or treat a chassis-dyno result as factory crankshaft horsepower; drivetrain loss, correction method, fuel and test conditions make those different measurements."]}
  ],faqs:[{q:"How much horsepower does a 2011 Mustang GT have?",a:"Ford rates the launch-year 5.0L Coyote Mustang GT at 412 hp."},{q:"How much horsepower does a 2018 Mustang GT have?",a:"Ford's 2018 specification sheet lists 460 hp for the 5.0L GT."},{q:"What are the 2024 Mustang horsepower ratings?",a:"Ford lists 315 hp for EcoBoost, 480 hp for GT, 486 hp for an active-valve-exhaust GT and 500 hp for Dark Horse, on the stated premium-fuel basis."},{q:"Can classic gross horsepower be compared directly with modern net horsepower?",a:"No. The measurement standards and installed accessories differ, so the figures need their historical rating context."}]},
  "bmw/328i/brake-rotor-torque":{sections:[
    {heading:"The 16-N·m screw is only a locating fastener",paragraphs:["The small countersunk screw holds the disc against the hub while the wheel is off. Final braking and wheel clamp loads do not pass through it in the same way they pass through caliper hardware and wheel bolts. Tightening it to a large wheel or carrier value can strip the hub or make future removal difficult.","Clean corrosion from the hub contact face, seat the disc without debris underneath and use a new retaining screw where BMW directs. Excessive rust scale creates runout that torque cannot correct. Check disc runout and minimum thickness by the complete brake procedure."]},
    {heading:"Guide, carrier and wheel fasteners are separate jobs",paragraphs:["The cited Teves example lists 30 N·m for its covered guide screw, but that is not permission to use 30 N·m on every 328i caliper. Front versus rear, caliper supplier and brake option change hardware. BMW's rotor procedure calls for replacement of removed carrier screws and points to axle-specific torque entries.","Support the caliper so its hose is not loaded, keep friction surfaces free of oil, replace discs in axle pairs and install new pads with new discs as directed. Finish with the separate wheel-bolt specification using clean, dry threads and a calibrated wrench; the rotor screw's 16 N·m never substitutes for wheel torque."]}
  ],faqs:[{q:"What is the BMW E9x brake rotor retaining-screw torque?",a:"The covered E90 service example lists 16 N·m (12 lb-ft) for the disc-to-hub screw."},{q:"Is 16 N·m the caliper-carrier torque?",a:"No. Carrier screws use a separate, much higher axle- and caliper-specific specification."},{q:"Can the retaining screw be reused?",a:"BMW's cited disc procedure directs replacement of the screw during installation."},{q:"Why can a new rotor still have runout?",a:"Rust or debris between the hub and disc can prevent flat seating. Clean the contact face and measure by the proper procedure."}]},
  "bmw/m3/horsepower-by-year":{sections:[
    {heading:"The U.S. generation progression",paragraphs:["The U.S. M3 moved from the E30's 192-hp four-cylinder to a 240-hp E36 inline-six, then to the 333-hp E46. The E9x changed direction with a 414-hp naturally aspirated V8, while the F8x returned to six cylinders with turbocharging and a 425-hp launch rating.","For 2025, BMW separates three G80 outputs: 473 hp for the rear-drive manual M3, 503 hp for M3 Competition and 523 hp for Competition xDrive. The range is trim- and drivetrain-specific, not evidence that every G80 has been uprated to 523 hp."]},
    {heading:"Keep U.S., European and special-edition figures apart",paragraphs:["BMW sold materially different E30 and E36 calibrations across markets. European historical charts often show 200–238 hp E30 variants and 286- or 321-hp E36 models, while the U.S. generation figures are 192 and 240 hp. Both can be correct for their market.","Special editions further complicate a simple generation table: Competition Package, CS and limited models can exceed the standard car. Record model year, market, body/chassis and full trim before quoting output, and preserve whether the source uses hp, PS or kW rather than silently converting labels."]}
  ],faqs:[{q:"How much horsepower does a U.S. E30 M3 have?",a:"BMW USA lists 192 hp for the U.S.-market E30 M3."},{q:"How much horsepower does an E46 M3 have in the U.S.?",a:"BMW USA's generation history lists 333 hp."},{q:"How much horsepower does the V8 E9x M3 have?",a:"The U.S. E9x generation is rated at 414 hp."},{q:"What are the 2025 BMW M3 outputs?",a:"BMW lists 473 hp for M3, 503 hp for Competition and 523 hp for Competition xDrive."}]},
  "bmw/5-series/battery-replacement":{sections:[
    {heading:"Registration and coding solve different problems",paragraphs:["Battery registration records a replacement event in the F10's energy-management system. It allows charging strategy and battery-aging calculations to begin from a new-battery baseline; disconnecting the old battery or clearing ordinary fault codes does not perform that service function.","BMW separates registration from battery retrofitting. A like-for-like replacement is registered, while a change in rated capacity or a switch between conventional lead-acid and AGM requires the vehicle data to be programmed for the new specification. A scan tool that only offers 'register battery' cannot safely authorize an arbitrary capacity change."]},
    {heading:"Choose and install the battery by vehicle assignment",paragraphs:["Read the existing label, verify the VIN parts assignment and match case dimensions, terminal orientation, venting, hold-down and rated specification. AGM is required on applications assigned AGM; BMW permits a standard battery to be replaced by an AGM with the same specifications only when the corresponding programming requirements are satisfied.","Before disconnecting, follow BMW's approved power-down and memory-support rules rather than attaching an improvised live feed. Secure the vent tube and hold-down, keep polarity protected, then register the completed replacement through Service functions > Body > Voltage supply > Register battery replacement. Investigate stored charging or IBS faults instead of assuming a new battery fixes the underlying cause."]}
  ],faqs:[{q:"Does a 2011 BMW 528i battery need registration?",a:"Yes, BMW's procedure requires registration after replacement on an F10 equipped with the Intelligent Battery Sensor or power module."},{q:"Is registering a BMW battery the same as coding it?",a:"No. Registration records the new battery; changing capacity or chemistry also requires programming the vehicle data for the retrofit."},{q:"What amp-hour battery does every F10 528i use?",a:"There is no safe universal answer. Use the VIN assignment and installed label because equipment and market affect battery specification."},{q:"Can a standard battery be replaced with AGM?",a:"BMW allows AGM substitution at the same specification in its guidance, but the vehicle's assigned part and any required programming must still be confirmed."}]},
  "hyundai/tucson/towing-capacity":{sections:[
    {heading:"Trailer brakes create the two published limits",paragraphs:["Hyundai's 2026 U.S. comparison table gives the gasoline Tucson a 2,750-lb maximum when the trailer has brakes and a 1,650-lb maximum without them. The higher number is not permission to tow an unbraked 2,750-lb trailer; the braking condition is part of the rating.","The page lists those ceilings across SE, SEL, SEL Plus, XRT, SEL Premium and Limited. It identifies a tow hitch as standard on XRT and an accessory on other trims, but hitch availability is not the whole towing package. Confirm wiring, ball mount, trailer-brake equipment and owner-manual requirements for the exact vehicle."]},
    {heading:"Work backward from payload, tongue load and equipment",paragraphs:["Load the trailer as it will travel and weigh it rather than relying on an empty brochure figure. Tongue weight rests on the Tucson and consumes payload alongside passengers, luggage, roof cargo and accessories. Keep the result within the certification-label GVWR and both axle ratings even when trailer weight is below 2,750 lb.","Use the lowest rating in the complete chain: vehicle, receiver, ball mount, ball, coupler, trailer, tires and any local legal limit. Balance cargo correctly and do not reduce tongue load to an unstable value simply to regain payload. For hills, heat or repeated towing, follow Hyundai's operating and maintenance guidance rather than treating the advertised maximum as a routine target."]}
  ],faqs:[{q:"How much can a 2026 Hyundai Tucson tow with trailer brakes?",a:"Hyundai publishes a maximum of 2,750 lb for the listed U.S. gasoline trims when the trailer is equipped with brakes."},{q:"What is the 2026 Tucson limit without trailer brakes?",a:"The official comparison table lists 1,650 lb maximum without trailer brakes."},{q:"Does the 2,750-lb rating mean every hitch can carry that trailer?",a:"No. The receiver, ball mount, ball, coupler and trailer must each be rated appropriately, and vehicle payload and axle limits still apply."},{q:"Does tongue weight count against Tucson payload?",a:"Yes. Tongue load is vehicle load and must be counted with occupants, cargo and accessories."}]},
  "subaru/forester/tire-size":{sections:[
    {heading:"The two factory 2012 tire-and-wheel rows",paragraphs:["For the covered naturally aspirated Forester, Subaru pairs P215/65R16 96H tires with 16 x 6.5 J/JJ wheels and P225/55R17 95H tires with 17 x 7 J/JJ wheels. Both wheel rows specify 48-mm offset and a 100-mm pitch-circle diameter.","These dimensions describe factory combinations, not universal aftermarket approval. A replacement wheel also needs the correct center-bore fit, lug-seat geometry, load rating and caliper/suspension clearance. Offset changes can alter bearing load, steering feel and tire-to-body clearance even when diameter and bolt circle match."]},
    {heading:"AWD replacement and pressure checks",paragraphs:["Subaru's all-wheel-drive system makes rolling-circumference matching important. Replace tires with the specified size and comparable construction/load capability, measure remaining tread on all four, and follow Subaru's limits for circumference differences rather than fitting one noticeably different tire because its sidewall code looks close.","Set cold inflation from the driver-door tire-information label, not from the maximum pressure molded into the tire. The service table intentionally points to that vehicle label. Recheck after temperature changes, rotations or load changes, and have alignment and suspension inspected when wear is uneven across an axle."]}
  ],faqs:[{q:"What tire sizes are listed for a 2012 Subaru Forester 2.5?",a:"The cited table lists P215/65R16 96H and P225/55R17 95H factory packages."},{q:"What wheel sizes go with those tires?",a:"The 16-inch tire uses a 16 x 6.5 J/JJ wheel; the 17-inch tire uses a 17 x 7 J/JJ wheel."},{q:"What are the factory offset and pitch-circle diameter?",a:"Both listed rows use 48-mm offset and a 100-mm pitch-circle diameter."},{q:"Can tire pressure be taken from the sidewall?",a:"No. Use the cold-pressure values on the driver's door-pillar tire label; the sidewall number is not the vehicle's normal setting."}]},
  "subaru/outback/alternator-amperage":{sections:[
    {heading:"Rated output versus the factory test points",paragraphs:["The Mitsubishi A003TG2391ZC is rated at 110 A, but diagnosis is not based on seeing 110 A at idle. Subaru's controlled minimum-output points rise with test speed: 50 A at 1,500 rpm, 91 A at 2,500 rpm and 105 A at 5,000 rpm. Temperature, load, battery state and test setup are part of a valid comparison.","The published regulated-voltage range is 14.1–14.8 V at 20°C. Charging voltage changes with conditions, so one dashboard reading does not prove alternator failure. Use the factory test method and safe equipment; the high-speed table value is not an instruction for an under-hood free-rev test."]},
    {heading:"Confirm the circuit before replacing the alternator",paragraphs:["Test battery condition first, then inspect belt tension and pulley condition. Measure voltage drop across the positive cable and ground path under load, and check terminals, fusible links and connectors. Resistance elsewhere can reduce delivered current even when the generator itself is capable.","For replacement, match the Subaru/Mitsubishi part assignment, mounting ears, pulley, connector and regulator behavior—not only the advertised amp rating. A physically similar high-output unit can create belt, wiring or control problems. After installation, verify belt tracking, charging voltage and loaded operation without leaving tools near the rotating drive."]}
  ],faqs:[{q:"How many amps is the 2005 Subaru Outback 2.5 alternator?",a:"The cited non-turbo 2.5L table rates Mitsubishi model A003TG2391ZC at 110 amps."},{q:"What voltage should the factory alternator regulate at?",a:"Subaru lists 14.1–14.8 V at 20°C (68°F) under the specified test conditions."},{q:"Should a 110-amp alternator produce 110 amps at idle?",a:"No. Output follows load and speed; Subaru's minimum controlled-test point is 50 A at 1,500 rpm."},{q:"Can any higher-amp Outback alternator be installed?",a:"No. Match the exact part assignment, mounts, pulley, connector and regulator/control characteristics."}]},
  "toyota/camry/serpentine-belt-diagram":{sections:[
    {heading:"Trace the two routes before loosening either tensioner",paragraphs:["The main high-strength belt begins at the crankshaft and runs through the cooler compressor, water pump and generator with an automatic tensioner controlling the span. Toyota's routing figure shows the ribbed and back-side contacts; preserve that orientation because a smooth pulley should not be forced into a grooved-side route.","A second, shorter belt drives the vane pump from the crankshaft and includes an idler plus its own automatic tensioner. Label the two old belts before removal and compare length, rib count and construction with the replacements. The main compressor/generator belt requires the specified high-strength aramid-core construction."]},
    {heading:"Installation checkpoints that prevent immediate belt damage",paragraphs:["For the compressor/generator belt, route every pulley except the water pump, rotate the tensioner clockwise and slip the final span over the water-pump pulley. For the vane-pump belt, route every pulley except its tensioner, rotate that tensioner clockwise and complete the route there.","Inspect from above and through the right wheel opening to confirm every rib is seated, with special attention to the crankshaft pulley. Reinstall the apron seal, opening pad, under-cover hardware and wheel by the full procedure; Toyota lists 103 N·m (76 lb-ft) for the wheel nuts. Start only after tools are clear, then observe tracking briefly and shut down immediately if an edge walks off a pulley."]}
  ],faqs:[{q:"Does a 2010 Camry 2.5 have one serpentine belt?",a:"No. Toyota's 2AR-FE procedure shows separate compressor/generator and vane-pump V-ribbed belts."},{q:"Which accessories are on the main belt?",a:"The main route includes the crankshaft, A/C compressor, water pump, generator and automatic tensioner."},{q:"Which way are the belt tensioners rotated?",a:"Toyota directs both automatic tensioners clockwise to unload their respective belts."},{q:"Can an ordinary belt replace the compressor/generator belt?",a:"Use a Toyota genuine or equivalent high-strength aramid-core belt as specified for that drive."}]},
  "jeep/wrangler/bolt-pattern":{sections:[
    {heading:"What the JK wheel specification tells you",paragraphs:["The 2012 JK's five studs lie on a 127-mm circle, usually written 5 x 127 or 5 x 5 in. The service row further identifies 1/2-20 threads and a 60-degree cone nut. Those details matter because a nut with the wrong thread or seat can appear to tighten while failing to clamp the wheel correctly.","Jeep publishes a 125–180-N·m (92–132-lb-ft) range for the covered hardware. Use the exact wheel and owner/service instructions to select the intended value within that factory range, particularly with approved accessory wheels. Start every nut by hand and tighten across the five-lug pattern in stages."]},
    {heading:"Why a matching bolt circle is not enough",paragraphs:["A 5 x 127 wheel can still interfere with the brake caliper, steering linkage or suspension, or place the tire too far inward or outward. Verify center bore, backspacing/offset, width, diameter, load rating, tire envelope and cone-seat compatibility before purchase.","Clean the hub and wheel mounting faces so corrosion cannot hold the wheel off-center. Keep the factory dry threads free of oil and anti-seize unless the exact procedure provides a revised lubricated value. Recheck seating after service as directed for the installed wheel and investigate any looseness rather than repeatedly adding torque."]}
  ],faqs:[{q:"What is the bolt pattern on a 2012 Jeep Wrangler JK?",a:"It is 5 x 127 mm, also written 5 x 5 inches."},{q:"What thread and seat does the 2012 JK lug nut use?",a:"The cited service row specifies 1/2-20 threads and a 60-degree cone seat."},{q:"What is the factory lug-nut torque range?",a:"Jeep lists 125–180 N·m (92–132 lb-ft) for the covered 2012 JK wheel hardware."},{q:"Will every 5 x 127 wheel fit a Wrangler JK?",a:"No. Center bore, offset/backspacing, width, brake clearance, load rating and lug-seat design must also match."}]},
  "ford/explorer/fuel-tank-capacity":{sections:[
    {heading:"Reading Ford's three capacity rows correctly",paragraphs:["The 2026 manual separates the 2.3L non-hybrid, the larger non-hybrid engine group and the full hybrid. Select the row by the vehicle's actual powertrain rather than trim name alone: a badge or option package does not change a 17.9-gallon tank into the 20.2-gallon version.","The 3.0L and 3.3L non-hybrid row is 20.2 US gal, while the hybrid is 18.0 US gal. That 0.1-gallon difference between the 2.3L and hybrid is real in the table but too small to identify a vehicle from one fuel receipt; use VIN and engine information instead."]},
    {heading:"Why the pump rarely matches nominal tank volume",paragraphs:["A fuel gauge reaching E does not mean the tank contains zero fuel. Ford retains a reserve, and the filler can also shut off at slightly different points because of pump sensitivity, vehicle angle, temperature and fuel foaming. Nominal capacity is therefore not a promise that every empty-gauge refill will accept the published amount.","Track repeated refills only if diagnosing an apparent range or gauge problem. Reset the trip meter, fill consistently at the first automatic shutoff and compare several tanks. Do not deliberately run the tank dry to test capacity; loss of fuel pressure can strand the vehicle and is not a valid measurement method."]}
  ],faqs:[{q:"How many gallons does a 2026 Ford Explorer hold?",a:"The 2.3L non-hybrid holds 17.9 US gal, the 3.0L/3.3L non-hybrid row holds 20.2 US gal, and the full hybrid holds 18.0 US gal."},{q:"Why did my Explorer take fewer gallons than the manual lists?",a:"Published capacity is nominal maximum volume. Reserve fuel remains when the gauge reads empty, and pump shutoff, vehicle angle and temperature also affect a receipt."},{q:"Can I identify the tank from the trim badge?",a:"Not reliably. Match the VIN and installed powertrain to the capacity row; do not infer tank size from appearance or a single refill."},{q:"Should I drive until the Explorer runs out to verify capacity?",a:"No. Use the manual and repeatable fill records. Intentionally running dry can strand the vehicle and is not a precise or safe capacity test."}]},
  "nissan/rogue/tire-pressure":{sections:[
    {heading:"Match pressure to the tire-size row",paragraphs:["The 17-inch package is the important exception in the 2024 table: its front target is 36 psi and rear target is 33 psi. Both the 18- and 19-inch packages use 33 psi front and 30 psi rear. Reading only one number from an online snippet can therefore leave an axle three psi off target.","Read the size molded into the installed tire, then confirm it against the driver-door placard. If wheels or tires were changed, the placard still describes the factory package; a qualified tire professional should assess load capacity and inflation for a non-factory combination."]},
    {heading:"Set pressure cold and preserve the front/rear split",paragraphs:["Nissan's figures are cold pressures. Check before meaningful driving, not immediately after highway use. Heat raises pressure normally; bleeding a hot tire down to the cold target can leave it underinflated after it cools.","Use an accurate gauge, adjust all four tires, reinstall valve caps and inspect for damage or uneven wear. If one tire repeatedly loses pressure, repair the leak rather than compensating with frequent top-offs. Recheck the door label after tire service because front and rear values are not interchangeable on these packages."]}
  ],faqs:[{q:"What tire pressure does a 2024 Nissan Rogue use with 17-inch tires?",a:"With factory 235/65R17 tires, Nissan specifies 36 psi front and 33 psi rear when cold."},{q:"What pressure applies to 18- or 19-inch 2024 Rogue tires?",a:"The factory 235/60R18 and 235/55R19 rows both specify 33 psi front and 30 psi rear, cold."},{q:"Is the PSI molded on the tire sidewall the Rogue setting?",a:"No. The sidewall shows a tire limit, not the vehicle's recommended operating pressure. Use the driver-door placard."},{q:"Should I lower a warm Rogue tire to the cold specification?",a:"No. Let it cool and recheck; bleeding a warm tire to the cold target usually leaves it underinflated later."}]},
  "jeep/wrangler/towing-capacity":{sections:[
    {heading:"The 2024 two-door and four-door split",paragraphs:["In the cited chart, body length is decisive. The covered two-door 2.0L and 3.6L rows stop at 2,000 lb gross trailer weight and 200 lb tongue weight. Covered four-door gasoline and 4xe rows reach 3,500 lb and 350 lb tongue weight.","Do not apply a rating from another model year because the word Wrangler matches. Axle ratio, powertrain, body style and factory equipment change across the range. Confirm the vehicle's exact chart row and installed hitch before connecting a trailer."]},
    {heading:"Payload can become the limiting number first",paragraphs:["Tongue weight presses on the Wrangler like cargo. A trailer at the 3,500-lb ceiling with 350 lb on the hitch has already consumed 350 lb of the vehicle's occupant-and-cargo allowance before passengers, recovery gear or luggage are counted.","Calculate loaded trailer weight at a scale, verify tongue weight, and compare the complete combination with GVWR, GAWR and GCWR. The legal and mechanical limit is the lowest rating among the Jeep, hitch, ball mount, coupler, trailer and tires—not simply the largest number in the towing table."]}
  ],faqs:[{q:"How much can a 2024 two-door Jeep Wrangler tow?",a:"The cited 2.0L and 3.6L two-door rows are rated for 2,000 lb maximum gross trailer weight with 200 lb maximum tongue weight."},{q:"How much can a 2024 four-door Wrangler tow?",a:"The covered 2.0L, 3.6L, 6.4L and 4xe four-door rows list 3,500 lb maximum gross trailer weight and 350 lb maximum tongue weight."},{q:"Does trailer tongue weight count as Wrangler payload?",a:"Yes. Tongue weight, occupants, cargo and accessories all consume the vehicle's available payload."},{q:"Can I use this 2024 chart for an older JK Wrangler?",a:"No. Use the owner information for the exact model year, body style, engine, axle and factory towing equipment."}]},
  "nissan/pathfinder/towing-capacity":{sections:[
    {heading:"What changes the 3,500-lb Pathfinder into a 6,000-lb configuration",paragraphs:["The 6,000-lb figure is conditional. Nissan pairs it with qualifying trim and towing equipment; the standard maximum is 3,500 lb. A V6 badge alone does not prove that the hitch, cooling, wiring and other required equipment are present.","Identify the exact trim and package from the window sticker, build data or dealer parts information, then verify the current towing section for the vehicle. Aftermarket hitch installation does not automatically raise the manufacturer's rating."]},
    {heading:"Calculate the combination before choosing a trailer",paragraphs:["Use the trailer's loaded weight, not its empty or dry brochure number. Add water, batteries, propane, cargo and installed options, then confirm tongue weight with a suitable scale. That tongue load reduces the Pathfinder's remaining allowance for people and luggage.","Compare the result with the door-label payload, GVWR, front and rear axle ratings and GCWR. Trailer brakes and weight-distributing equipment must follow Nissan's instructions and applicable law. If any component has a lower rating than the vehicle maximum, the lower figure governs."]}
  ],faqs:[{q:"How much can a 2026 Nissan Pathfinder tow as standard?",a:"Nissan lists a 3,500-lb standard maximum. The 6,000-lb figure requires a qualifying properly equipped configuration."},{q:"Which 2026 Pathfinder can tow 6,000 lb?",a:"Qualifying trims with the applicable Premium package or factory towing equipment can reach the published maximum; confirm the exact vehicle and brochure equipment table."},{q:"Does installing an aftermarket hitch create a 6,000-lb rating?",a:"No. A hitch cannot increase Nissan's vehicle rating or substitute for the required factory configuration and supporting equipment."},{q:"Should trailer dry weight be used for the calculation?",a:"No. Use actual loaded trailer weight and tongue weight, including cargo, water, fuel, batteries and accessories."}]},
  "jeep/gladiator/payload":{sections:[
    {heading:"Model maximum versus the label on one truck",paragraphs:["The 1,725-lb figure is Jeep's maximum for a qualifying 2024 Gladiator configuration. Different trims, options and factory equipment change curb weight, so a highly equipped truck can have materially less payload even though the exterior badge is the same.","Open the driver door and read the Tires and Loading Information label stating the combined weight of occupants and cargo. That vehicle-specific figure is the practical starting point; do not replace it with the website maximum."]},
    {heading:"How payload disappears in normal use",paragraphs:["Count the driver, every passenger, items in the cab and bed, dealer-installed equipment and aftermarket accessories. A bed rack, winch, larger spare, steps and recovery gear may consume hundreds of pounds before the first bag of cargo is loaded.","When towing, include the trailer's actual tongue weight and hitch hardware in the load calculation. Towing capacity and payload are separate constraints: a truck can be below 7,700 lb of trailer weight yet exceed payload or a rear-axle rating first. Weigh the loaded axles when operating near a limit."]}
  ],faqs:[{q:"What is the maximum payload of a 2024 Jeep Gladiator?",a:"Jeep advertises up to 1,725 lb of 4x4 payload when properly configured."},{q:"Does every 2024 Gladiator carry 1,725 lb?",a:"No. Options and trim change curb weight. Use the occupant-and-cargo number on the actual truck's door-jamb label."},{q:"Does trailer tongue weight reduce Gladiator payload?",a:"Yes. Tongue weight and hitch hardware count along with occupants, bed cargo and accessories."},{q:"Is payload the same as towing capacity?",a:"No. Jeep lists up to 1,725 lb payload and up to 7,700 lb gas towing as separate maximums, each subject to configuration and loading limits."}]},
  "nissan/sentra/tire-size":{sections:[
    {heading:"The 2024 Sentra's three factory packages",paragraphs:["Nissan's specification table pairs 205/60R16 tires with 16 x 6.5 wheels, 215/50R17 tires with 17 x 7 wheels and 215/45R18 tires with 18 x 7.5 wheels. Offsets are 40, 48 and 43 mm respectively, so diameter alone does not define an interchangeable wheel.","Read the driver-door label and the markings on the installed wheel and tire before ordering. Load index, speed rating, width, offset, center fit and brake clearance all matter; a tire that can be stretched onto a rim is not automatically an approved combination."]},
    {heading:"Pressure and winter-chain restrictions",paragraphs:["The manual's S, SV and SR pressure table specifies 33 psi front and rear, cold, for all three road-tire sizes. That does not make the maximum pressure molded into the sidewall a suitable target. Adjust cold, reinstall valve caps and investigate any tire that repeatedly loses air.","Nissan warns against installing tire chains or cables on the covered 215/50R17 and 215/45R18 sizes because of clearance and vehicle-damage risk. Its manual points owners who require chains toward the 205/60R16 configuration and the full chain instructions; local law and exact approved hardware still apply."]}
  ],faqs:[{q:"What tire sizes are listed for the 2024 Nissan Sentra?",a:"The U.S. manual lists 205/60R16, 215/50R17 and 215/45R18 road tires."},{q:"What is the 2024 Sentra cold tire pressure?",a:"Nissan lists 33 psi (230 kPa) front and rear for all three factory road-tire rows."},{q:"Can 17- or 18-inch 2024 Sentra tires use chains?",a:"Nissan warns not to install chains or cables on the covered 215/50R17 and 215/45R18 sizes because they can damage the vehicle."},{q:"Is matching diameter enough when buying Sentra wheels?",a:"No. Match wheel width, offset, load rating, mounting dimensions and brake clearance as well as tire diameter."}]},
  "honda/cr-v/spark-plug-gap":{sections:[
    {heading:"How to use Honda's gap range",paragraphs:["The 1.0–1.1-mm range is a new-plug specification for this 2005 2.4L application, not permission to reshape an iridium electrode until it fits. Honda explicitly says to replace an iridium-tip plug when its gap is out of specification.","A correct number on a gauge does not validate the wrong plug. Verify the approved part number, reach, gasket seat, resistor and heat range. Compare all four removed plugs because deposits and wear patterns can reveal a cylinder-specific fuel, oil or cooling problem."]},
    {heading:"Installation checkpoints on the K24 aluminum head",paragraphs:["Work with the engine cool, clear dirt from the plug wells and remove one coil position at a time. Thread each plug to its seat by hand; early resistance signals contamination or cross-threading and must not be overcome with a ratchet.","Use a calibrated torque wrench for 18 N·m on the clean-thread procedure. Excess lubricant changes friction and can over-stress the shell or head threads. After coil installation, ensure every connector locks and every boot seals before starting the engine."]}
  ],faqs:[{q:"What is the 2005 Honda CR-V 2.4L spark plug gap?",a:"Honda lists 1.0–1.1 mm, equivalent to 0.039–0.043 inch, for a new plug."},{q:"What is the spark plug torque for this 2005 CR-V?",a:"18 N·m, or 13 lb-ft, in the cited factory service row."},{q:"Can an out-of-gap iridium plug be adjusted?",a:"Honda's service instruction says not to adjust the gap of iridium-tip plugs; replace a plug that is outside specification."},{q:"Does this specification apply to a turbo CR-V?",a:"No. It is scoped to the 2005 2.4L application; later 1.5L turbo vehicles require their own approved plug and procedure."}]},
  "toyota/corolla/spark-plug-torque":{sections:[
    {heading:"What the 20-N·m figure covers",paragraphs:["Toyota's cited procedure calls for a 14-mm spark-plug wrench and 20 N·m on all four plugs in the 2010 Corolla 2ZR-FE. It is a torque value for this exact plug and aluminum-head application, not a universal Corolla number.","Before using it, confirm the engine code and approved plug. Later 2.0L engines, earlier Corolla families and non-U.S. applications can use different plug dimensions or service instructions even when the task looks identical from above."]},
    {heading:"Avoiding thread and coil damage",paragraphs:["Remove debris before loosening a plug and keep sockets square in the well. Start the replacement through several turns using only the extension or a short hose; a plug that will not turn freely should be backed out and inspected.","Torque on a cool engine with clean threads under the conditions Toyota specifies. Refit the coils without trapping boots or harnesses. If a misfire appears after service, check connector engagement, cracked porcelain and coil seating before assuming the firing order changed."]}
  ],faqs:[{q:"What is the 2010 Toyota Corolla 1.8 spark plug torque?",a:"Toyota specifies 20 N·m, equal to 15 lb-ft, for the 2ZR-FE procedure."},{q:"What size spark-plug wrench does the procedure identify?",a:"A 14-mm spark-plug wrench."},{q:"Can I use 15 lb-ft on every Corolla engine?",a:"No. This value is scoped to the 2010 1.8L 2ZR-FE; verify another engine and model year separately."},{q:"Should anti-seize be added before applying 20 N·m?",a:"Not unless the exact service or plug instructions explicitly account for lubricated threads, because lubrication changes clamp load."}]},
  "toyota/highlander/spark-plug-gap":{sections:[
    {heading:"New-plug reference versus used-plug limit",paragraphs:["Toyota provides two different measurements in this 2GR-FE row. The new-plug reference is 1.0–1.1 mm, while 1.4 mm is the maximum used-plug gap. Treating 1.4 mm as a setup target would intentionally install an over-wide gap.","Fine-wire plugs should be inspected without striking the center electrode. Replace cracked, contaminated or excessively worn plugs and keep the approved part numbers together as a set; gap alone does not establish heat range or reach."]},
    {heading:"Access and installation on the transverse V6",paragraphs:["The rear bank's restricted access can turn a simple measurement into an intake-component service. Follow the exact removal procedure, protect open ports and replace any gasket or single-use item the manual identifies rather than forcing tools between components.","Hand-start all six plugs and use the cited 18-N·m torque on the specified thread condition. Reconnect vacuum hoses, electrical connectors and intake seals methodically; a post-service lean code may come from an air leak rather than from the new plugs."]}
  ],faqs:[{q:"What is the new spark plug gap for a 2008 Highlander 3.5L?",a:"Toyota lists 1.0–1.1 mm, or 0.039–0.043 inch, as the new-plug reference."},{q:"What does the 1.4-mm figure mean?",a:"It is the maximum electrode gap for a used plug, not the setting for a new plug."},{q:"What is the 2008 2GR-FE spark plug torque?",a:"18 N·m, equal to 13 lb-ft, in the cited service data."},{q:"Can this gap be used for a later turbo Highlander?",a:"No. This answer is scoped to the 2008 3.5L 2GR-FE application."}]},
  "chevrolet/silverado-1500/spark-plug-gap-chart":{sections:[
    {heading:"Why older Silverado catalogs show conflicting gaps",paragraphs:["GM's service information for this 2004 5.3L incorporates a bulletin introducing an iridium replacement plug and its 0.040-inch factory gap. Older platinum listings and screenshots can show another value because they predate the updated plug design.","Use the current approved supersession for the VIN and read the instructions attached to that plug. Do not mix a legacy part number's gap with the later iridium replacement or assume that every 5.3L across two decades uses the same tune-up row."]},
    {heading:"Inspection and installation without regapping",paragraphs:["GM states that the replacement plug is set during manufacture and should not be changed. Confirm the gap carefully without forcing a wedge between fine electrodes; return a plug with shipping damage or an incorrect factory gap.","Remove dirt from the wells, start each plug by hand and tighten to the service row's 15 N·m on the specified clean-thread condition. Route boots away from exhaust heat and make sure each terminal clicks into place. Diagnose a remaining misfire by cylinder rather than opening all eight gaps."]}
  ],faqs:[{q:"What is the spark plug gap for the covered 2004 Silverado 5.3L?",a:"The updated GM service row specifies 0.040 inch, or 1.01 mm, for the identified iridium replacement plug."},{q:"Which plug number appears in the GM bulletin?",a:"GM P/N 12571164, cross-referenced there as ACDelco 41-985."},{q:"Should the 0.040-inch iridium plug be regapped?",a:"No. GM says its gap is set during manufacture and should not be changed; do not use a new plug found outside specification."},{q:"What torque is listed for the 2004 5.3L plug?",a:"15 N·m, or 11 lb-ft, in the matching service specification."}]},
  "dodge/charger/firing-order":{sections:[
    {heading:"Two engines, two completely different sequences",paragraphs:["The 2012 3.6L service row is the straight numerical sequence 1-2-3-4-5-6. The 5.7L HEMI row is 1-8-4-3-6-5-7-2. The fact that both were installed in a Charger does not make their coil layout or diagnostic workflow interchangeable.","Identify the engine from the VIN and under-hood information before using either sequence. This page does not silently extend the 5.7L value to the 6.4L SRT or to classic distributor-equipped Charger engines."]},
    {heading:"Using firing order during a P030x diagnosis",paragraphs:["A code such as P0304 identifies physical cylinder 4. It does not mean the fourth cylinder in the firing sequence. Locate that cylinder using the correct bank diagram, save freeze-frame data and inspect its plug, coil connector and harness without disturbing unrelated cylinders.","A coil swap can help isolate an ignition fault when the service procedure permits it: document original positions, move only the intended components and see whether the misfire follows. If it stays put, continue with injector control, compression, leak-down and air-leak checks instead of treating firing order as the repair."]}
  ],faqs:[{q:"What is the 2012 Dodge Charger 3.6L firing order?",a:"The cited factory service row lists 1-2-3-4-5-6."},{q:"What is the 2012 Charger 5.7L HEMI firing order?",a:"The cited factory service row lists 1-8-4-3-6-5-7-2."},{q:"Does P0304 mean the fourth firing event?",a:"No. It means a misfire associated with physical cylinder 4; use the correct engine's cylinder-location diagram."},{q:"Does this page establish the 6.4L SRT firing order?",a:"No. Its exact cited applications are the 2012 AWD 3.6L and AWD 5.7L."}]},
  "chevrolet/malibu/firing-order":{sections:[
    {heading:"Reading the 2012 2.4L ignition table",paragraphs:["GM groups firing order, gap and tightening torque in the same application table: 1-3-4-2, 1.0 mm and 20 N·m. Keeping those values together prevents a common mistake—using the four-cylinder sequence but a plug specification copied from the optional V6.","Confirm the 2.4L from VIN/RPO data before moving coils. The approved plug itself comes from the electronic parts catalog because part numbers can supersede while the mechanical application remains the same."]},
    {heading:"Using the order without misreading a misfire code",paragraphs:["Firing order describes combustion sequence; cylinder numbering identifies a physical bore. Record codes and freeze-frame data first, then locate the coded cylinder from the 2.4L diagram rather than counting to the same position in 1-3-4-2.","If a controlled coil swap is allowed, mark both positions and see whether the fault follows. A stationary misfire calls for plug, injector, wiring, compression and intake-leak checks—not rotation of components until the code disappears."]}
  ],faqs:[{q:"What is the 2012 Chevy Malibu 2.4 firing order?",a:"GM's table lists 1-3-4-2."},{q:"What plug gap accompanies that firing-order row?",a:"1.0 mm, or 0.040 inch."},{q:"What is the listed spark-plug torque?",a:"20 N·m, equal to 15 lb-ft."},{q:"Can this order be used for a 2012 Malibu 3.6L?",a:"No. The V6 has a different cylinder layout and its own ignition specifications."}]},
  "hyundai/elantra/spark-plug-torque":{sections:[
    {heading:"Torque range, gap and coil fastener are separate values",paragraphs:["Hyundai publishes 14.7–24.5 N·m for the plug and 9.8–11.8 N·m for the ignition-coil fastener. Confusing the two can leave a plug loose or damage the small coil bolt. Set the torque wrench from the correct row.","The same inspection procedure lists a 1.0–1.1-mm electrode gap. The specification image identifies SILZKR6B11 and RER8WMPB4, but a current parts catalog should confirm any supersession before purchase."]},
    {heading:"A clean installation protects the aluminum head",paragraphs:["Work cold, disconnect coils by their locks rather than pulling wires and remove debris before the plugs come out. The service procedure warns against letting contaminants enter through the plug holes.","Thread replacements fully by hand, then apply the published clean-thread range. Seat coils squarely so their sealing caps meet the cover, tighten their separate fasteners and reconnect every lock. A fresh misfire after service often traces to seating or connection, not the plug gap."]}
  ],faqs:[{q:"What is the 2012 Elantra 1.8L spark-plug torque?",a:"Hyundai lists 14.7–24.5 N·m, or 10.8–18.1 lb-ft."},{q:"What is the ignition-coil bolt torque?",a:"9.8–11.8 N·m, or 7.2–8.7 lb-ft."},{q:"What plug gap does the procedure list?",a:"1.0–1.1 mm, equivalent to 0.0394–0.0433 inch."},{q:"Does this apply to a turbo Elantra?",a:"No. It is scoped to the 2012 naturally aspirated 1.8L application."}]},
  "honda/odyssey/brake-pad-thickness":{sections:[
    {heading:"Measure all eight pads, not one convenient outer pad",paragraphs:["Honda separates front and rear new thickness but gives both axles the same 1.6-mm service limit. Measure the friction lining only at the thinnest point on each inner and outer pad; the steel backing plate is not part of the reading.","Inner pads can wear faster when slide pins or pistons do not move freely. Record the measurements by wheel and position. A large side-to-side or inner-to-outer difference is diagnostic information, not a value to average."]},
    {heading:"Thickness is only one replacement criterion",paragraphs:["Replace pads that are cracked, separated, oil- or brake-fluid-contaminated, or severely tapered even above 1.6 mm. Inspect rotor thickness and condition, caliper boots, slides and hose routing at the same time.","The limit is not an ideal planning target. Braking duty, towing, hills and driving conditions change wear rate, so schedule service with usable margin and follow the exact bedding procedure for the installed pad and rotor combination."]}
  ],faqs:[{q:"How thick are new 2010 Odyssey front pads?",a:"Honda lists 11.0–12.0 mm."},{q:"How thick are new rear pads?",a:"The listed rear range is 9.5–10.5 mm."},{q:"What is the brake-pad service limit?",a:"1.6 mm (0.06 inch) at both front and rear for the covered 2010 application."},{q:"Should uneven pads be averaged?",a:"No. Use the thinnest usable point and investigate caliper, slide or mounting problems causing uneven wear."}]},
  "toyota/rav4/brake-pad-thickness":{sections:[
    {heading:"Toyota's front and rear measurements",paragraphs:["The covered 2AR-FE table begins at 12.0 mm front and 10.5 mm rear, with a 1.0-mm minimum at both axles. These are lining measurements, so exclude the backing plate and measure each pad separately.","Do not copy the 1.0-mm limit into a different RAV4 generation without checking its brake package. Hybrid regeneration, electronic parking brakes, caliper revisions and rotor sizes change across the nameplate's long production run."]},
    {heading:"Interpreting wear before the limit",paragraphs:["A pad can require replacement above the numerical minimum because of taper, cracking, glazing or contamination. Compare inner and outer pads and both sides of the axle; unevenness often points to seized hardware or a piston/boot problem.","Measure rotor thickness and inspect runout condition as required before installing pads. Clean and lubricate only the specified sliding surfaces with the correct brake product, keep friction faces dry and follow the proper bedding routine."]}
  ],faqs:[{q:"What is the new front pad thickness for the covered 2010 RAV4?",a:"Toyota lists 12.0 mm (0.472 inch)."},{q:"What is the new rear pad thickness?",a:"10.5 mm (0.413 inch)."},{q:"What is the minimum pad thickness?",a:"1.0 mm (0.0394 inch) for both front and rear in the cited row."},{q:"Does this chart cover a RAV4 Hybrid or Prime?",a:"No. It is scoped to the 2010 4WD 2.5L 2AR-FE application."}]},
  "bmw/3-series/brake-rotor-size":{sections:[
    {heading:"Why the E90 table contains several rotor diameters",paragraphs:["BMW states that engine, transmission and equipment specification can change the installed discs. Its E90 table therefore spans front combinations from 292 x 22 mm through 360 x 30 mm and rear combinations from 296 x 10 mm through 350 x 24 mm.","Those are catalog possibilities, not a shopping list for one 328i. Assign the disc by VIN and ETK, then match diameter, nominal thickness, venting, hat geometry and any left/right construction. Wheel diameter cannot identify the brake option reliably."]},
    {heading:"Minimum thickness and replacement rules",paragraphs:["For ordinary discs in general inspection, BMW describes a nominal-thickness-minus-2.4-mm reference; M/perforated discs use a different 1.6-mm rule. The minimum stamped on the disc remains the direct check for the installed part.","Measure at several points away from the wear lip. BMW directs disc replacement in axle pairs and requires new pads with new discs. Clean hub contact surfaces carefully because corrosion or debris can create lateral runout even with a dimensionally correct new rotor."]}
  ],faqs:[{q:"What size brake rotors fit a 2011 BMW E90?",a:"BMW lists multiple front and rear combinations; the correct one must be selected by VIN and ETK rather than model badge alone."},{q:"What front sizes appear in the E90 table?",a:"Published combinations span 292–360 mm diameter and 22–30 mm nominal thickness, depending on equipment."},{q:"What rear sizes appear in the table?",a:"Published combinations span 296–350 mm diameter and 10–24 mm nominal thickness."},{q:"Can new pads be installed on a rotor at minimum thickness?",a:"Follow BMW's exact minimum-thickness rule and installed-disc stamping; the cited procedure requires adequate thickness for the life of another pad set and pairs new discs with new pads."}]},
  "hyundai/sonata/head-bolt-torque":{sections:[
    {heading:"The two angle passes are not optional",paragraphs:["Stage one establishes the initial 32.4–36.3-N·m clamp in the illustrated order. Hyundai then requires 90–95 degrees and another 90–95 degrees. Stopping after the first torque pass leaves the joint far short of the designed bolt stretch.","Use an angle gauge or torque-angle wrench and mark completed bolts so none is skipped or turned twice. Follow the factory sequence diagram; this page does not invent coordinates where the cited figure is required."]},
    {heading:"Bolt condition and surface preparation",paragraphs:["The procedure says to use new bolts and not apply engine oil. Reusing stretched bolts or lubricating a dry-thread specification changes the relationship between wrench input, angle and clamp load.","Before assembly, verify flatness and surface condition by the full engine procedure, clean bolt holes and ensure no liquid can hydraulically lock beneath a fastener. Use the correct gasket orientation and dowels, then carry out each stage without long, uneven interruptions."]}
  ],faqs:[{q:"What is stage one for the 2012 Sonata 2.4 head bolts?",a:"32.4–36.3 N·m, or 23.9–26.8 lb-ft, in the factory sequence."},{q:"What are stages two and three?",a:"A 90–95-degree turn for every bolt in sequence, followed by a second 90–95-degree pass."},{q:"Can the cylinder-head bolts be reused?",a:"No. Hyundai's cited procedure says always use new cylinder-head bolts."},{q:"Should oil be applied to the bolts?",a:"No. The procedure explicitly says not to apply engine oil to these head bolts."}]},
  "dodge/durango/transmission-fluid":{sections:[
    {heading:"Service fill and overhaul fill answer different questions",paragraphs:["The 65RFE 4WD service-fill figure is 6.5 qt, while 16.9 qt is the overhaul/dry reference. A pan service leaves fluid in the converter, cooler and passages, so using the overhaul number after an ordinary drain risks severe overfill.","Even dry capacity can vary with cooler type and line volume. Measure recovered fluid as a planning check, then use the transmission-specific temperature and level procedure; quantity alone cannot prove the final level."]},
    {heading:"Transmission identity controls the fluid row",paragraphs:["Both the cited 65RFE and NAG1 rows specify Mopar ATF+4, but their capacities differ. Later Durangos introduced eight-speed units with a different fluid and level procedure, so a modern bottle recommendation must not be back-applied by model name.","Confirm the transmission code before opening the system. Keep tools and containers clean, replace the specified filter/seal components and do not mix unapproved universal fluids merely because the label mentions Chrysler compatibility."]}
  ],faqs:[{q:"What fluid does the 2012 Durango 65RFE use?",a:"The cited factory table specifies Mopar ATF+4."},{q:"What is the 65RFE 4WD service-fill amount?",a:"Approximately 6.5 US qt (6.2 L)."},{q:"What does the 16.9-qt figure mean?",a:"It is the 4WD 65RFE overhaul/dry-fill reference, not a routine drain-and-fill amount."},{q:"Can later Durango eight-speed fluid be used here?",a:"No. Match the exact transmission; later eight-speed applications use their own specified fluid and procedure."}]},
  "jeep/cherokee/alternator-replacement":{sections:[
    {heading:"Why the 2000 XJ has three factory ratings",paragraphs:["Jeep lists 81-, 117- and 124-amp Denso units under different part numbers. Electrical package, mounting and calibration determine the installed unit; output rating alone is not permission to substitute the largest alternator.","Read the label and part number before removal and confirm the superseding catalog entry by VIN. Match pulley alignment, connector, case clocking and mounting ears as well as amperage."]},
    {heading:"Test the charging system before replacing the generator",paragraphs:["The table's minimum test outputs—57, 88 and 90 amps—belong to controlled factory test conditions. A low voltage reading at idle can also come from belt slip, battery condition, cable resistance, poor grounds or regulator control.","Load-test the battery, inspect the belt and measure voltage drop on positive and ground paths before condemning the alternator. Disconnect the battery for removal, maintain correct belt routing and use the 55-N·m mounting/pivot value only on the covered fasteners."]}
  ],faqs:[{q:"What alternator ratings are listed for the 2000 Jeep Cherokee 4.0?",a:"Jeep lists Denso units rated at 81, 117 and 124 amps under three separate part numbers."},{q:"Can I install the 124-amp unit in every 2000 Cherokee?",a:"Do not assume that. Match the VIN, installed part number, mounting, pulley, connector and electrical package."},{q:"What are the minimum factory test outputs?",a:"57 A for the 81-A unit, 88 A for the 117-A unit and 90 A for the 124-A unit."},{q:"What is the listed mounting-fastener torque?",a:"55 N·m for the covered generator mounting and pivot fasteners."}]},
  "subaru/legacy/serpentine-belt":{sections:[
    {heading:"This accessory belt is not the timing belt",paragraphs:["The covered 2.5L SOHC engine uses an automatic tensioner for its external V-belt. Rotating that tensioner clockwise unloads the accessory belt; it does not expose or set the engine's internal cam timing system.","Photograph routing and verify the engine before removal. Turbo and six-cylinder Legacy applications use different layouts, so a routing sketch from another engine can place the smooth and ribbed belt faces on the wrong pulleys."]},
    {heading:"Inspection before the engine is restarted",paragraphs:["Subaru rejects a belt contaminated by oil, grease or coolant and calls for clean pulley grooves. Inspect for cracks, tears, exposed cords and edge damage, then check the tension indicator is inside its limit.","After installing, turn the system by hand where the full procedure permits and inspect every groove. Use 33 N·m for the tensioner assembly and 20 N·m for the idler fastener only after identifying each fastener correctly."]}
  ],faqs:[{q:"Which way is the 2012 Legacy 2.5 tensioner rotated for removal?",a:"Clockwise, using the proper tool to unload the accessory belt."},{q:"What is the tensioner-assembly fastener torque?",a:"33 N·m (24.3 lb-ft)."},{q:"What is the idler-pulley fastener torque?",a:"20 N·m (14.8 lb-ft)."},{q:"Can an oil-contaminated belt be reused after cleaning?",a:"No. Subaru's cited procedure says not to use a belt contaminated with oil, grease or coolant."}]},
  "chevrolet/equinox/oil-filter-size":{sections:[
    {heading:"Why physical size is the wrong buying shortcut",paragraphs:["This 2.4L uses a cartridge insert under a reusable cap. A dimensionally similar insert can differ in media, end construction or bypass behavior, and GM warns that an incorrect filter can fail or cause severe engine damage.","Use VIN/engine and the current OE cross-reference. Inspect the replacement and new cap seal before opening the housing; do not select a spin-on filter from a later Equinox engine because the model name matches."]},
    {heading:"Cap, seal and drain-plug procedure",paragraphs:["Use the EN-44887-style cap tool squarely, replace the cartridge and seal, and coat the new seal with fresh engine oil. GM lists 22 N·m for the cap and warns that overtightening can crack it and create a leak.","The drain plug receives a new seal and 25 N·m in the cited procedure. Refill with the exact oil specification, run until pressure is established, inspect both sealing points and finish the level check on appropriate ground."]}
  ],faqs:[{q:"Is the 2012 Equinox 2.4 oil filter spin-on?",a:"No. It is a replaceable cartridge insert inside a reusable cap."},{q:"What is the oil-filter-cap torque?",a:"22 N·m (16 lb-ft)."},{q:"What tool does GM identify for the cap?",a:"EN-44887 or the proper equivalent oil-filter-cap wrench."},{q:"Can filter dimensions alone identify the correct cartridge?",a:"No. Use the VIN/engine and approved OE cross-reference because internal construction and bypass requirements matter."}]},
  "chevrolet/tahoe/rear-axle-torque":{sections:[
    {heading:"Identify 8.6, 9.5 LD or 10.5 before choosing a row",paragraphs:["Cover bolts and the fill plug happen to share values across the three listed axles, but bearing caps and ring-gear bolts do not. The gap is large: bearing caps range from 75 N·m on the 8.6 to 185 N·m on the 10.5.","Read the axle RPO and confirm housing/ring-gear identification through the service information. Do not use cover shape as the only evidence, especially after a vehicle has been modified or had an axle assembly replaced."]},
    {heading:"Internal differential work needs more than fastener torque",paragraphs:["Ring-gear and bearing-cap values are only pieces of a setup involving backlash, bearing preload, contact pattern, fastener condition and sometimes thread treatment. A correct wrench number cannot rescue an incorrect shim or reused one-time fastener.","The pinion nut is intentionally absent from the quick table because tightening establishes bearing preload. Follow the complete axle-specific build procedure and measure rotational torque; never substitute a generic final pinion-nut torque."]}
  ],faqs:[{q:"What is the 2012 Tahoe rear cover bolt torque?",a:"39 N·m (29 lb-ft) for the 8.6-, 9.5-LD and 10.5-inch rows in the cited table."},{q:"What is the rear axle fill-plug torque?",a:"33 N·m (24 lb-ft)."},{q:"Are bearing-cap bolts the same across all three axles?",a:"No. The table lists 75, 95 and 185 N·m for the 8.6-, 9.5-LD and 10.5-inch axles respectively."},{q:"What is the Tahoe pinion-nut torque?",a:"Do not use a generic final torque; pinion tightening is an axle-specific bearing-preload procedure."}]},
  "ram/2500/rear-axle-torque":{sections:[
    {heading:"The 11.5-inch AA row must be identified first",paragraphs:["The covered Ram manual also includes 10.5-inch and 302RBI rear-axle tables. These values belong only to the 11.5-inch AA assembly; confirm axle identity, ratio and service history before tightening internal parts.","The table lists 3.73 and 4.10 ratios and a 292-mm ring gear for this axle. Those descriptors help identification but do not replace the axle tag and parts information."]},
    {heading:"Rotating torque is a preload measurement",paragraphs:["For new pinion bearings the table gives 15–25 in-lb of torque to rotate; original bearings use 10–20 in-lb. These are measured rotational-resistance targets after setup, not values to dial into a wrench on the pinion nut.","Internal work also requires 0.005–0.007-in ring-gear backlash and the complete contact-pattern procedure. Use the cover, cap, ring-gear and flange bolt values only with the specified fastener preparation and sequence."]}
  ],faqs:[{q:"What is the 2012 Ram 2500 11.5-inch axle cover torque?",a:"40 N·m (30 lb-ft)."},{q:"What are the bearing-cap and ring-gear bolt torques?",a:"281 N·m (207 lb-ft) for bearing caps and 237 N·m (175 lb-ft) for ring-gear bolts."},{q:"What is the axle-flange bolt torque?",a:"129 N·m (95 lb-ft)."},{q:"Is 15–25 in-lb a pinion-nut tightening torque?",a:"No. It is the pinion torque-to-rotate target for new bearings and must be established through the full preload procedure."}]}
};

function makePage(j:Job):SpecRecord{
  const points=j.diagram==="firing"?(j.values[0]?.value.match(/\d/g)??["ID"]):j.values.map((_,i)=>String(i+1));
  const editorial=researchedEditorial[j.slug];
  const record:SpecRecord={slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:j.category,title:j.title,
    metaDescription:`${j.title} with application table, generation boundaries, verification steps, cautions and official manufacturer lookup.`,answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:[j.source,...(j.extraSources??[])],reviewed,
    featureImage:j.image==="engine"?engineImage:vehicleImage,featureOverlay:true,
    diagram:{type:j.diagram??"main",title:`Interactive ${j.model} specification guide`,caption:"Use this visual as an orientation aid. The exact VIN, engine, trim and manufacturer document control the specification.",points},
    intro:[j.answer,j.scope],steps:[],guides:["identifying-your-exact-vehicle"],
    sections:[...(editorial?.sections??[]),{heading:`Application boundaries for ${j.model}`,paragraphs:[j.scope,j.detail]}],
    // Hand-written FAQs where they exist; the generated block otherwise, which
    // faq-quality.ts correctly refuses to publish as FAQPage.
    faqs:editorial?.faqs??generalVehicleFaqs[j.slug]??[{q:`What are the ${j.keyword}?`,a:j.answer},{q:"Why does the specification vary?",a:j.scope},{q:"What should be checked before using the chart?",a:`${j.detail} Confirm the exact vehicle in the linked manufacturer source.`}]};
  return record;
}

export const generalVehicleSpecs:SpecRecord[]=jobs.map(makePage);
